/* Банк вопросов «Карта поляка» (из polski-trener), только для чтения. */
window.KARTA_CARDS = {"og_godlo":{"c":"ogolne","qru":"Как выглядит польский герб?","qpl":"Jak wygląda godło Polski?","apl":"Godło Polski to biały orzeł w złotej koronie na czerwonym tle. Orzeł ma złoty dziób i złote szpony.","aru":"Герб Польши — это белый орёл в золотой короне на красном фоне. У орла золотой клюв и золотые когти.","tr":"Гóдло Пóльски то бя́лы óжэл в злóтэй корóне на чэрвóным тле. Óжэл ма злóты дзюп и злóтэ шпóны.","mn":"","why":"Герб (godło) — один из главных государственных символов, вопрос про орла встречается на экзамене почти всегда.","p":0},"og_flaga":{"c":"ogolne","qru":"Какие цвета у польского флага?","qpl":"Jakie kolory ma flaga Polski?","apl":"Flaga Polski ma dwa kolory: biały na górze i czerwony na dole.","aru":"У флага Польши два цвета: белый сверху и красный снизу.","tr":"Флáга Пóльски ма два кóлоры: бя́лы на гýже и чэрвóны на дóле.","mn":"","why":"Цвета флага и их порядок (белый сверху) — базовый вопрос о символах государства.","p":0},"og_chrzest":{"c":"ogolne","qru":"Когда было крещение Польши и кто был тогда правителем?","qpl":"Kiedy był chrzest Polski i kto wtedy panował?","apl":"Chrzest Polski był w 966 roku. Wtedy panował książę Mieszko I. Przyjął chrzest dzięki swojej żonie Dobrawie.","aru":"Крещение Польши было в 966 году. Тогда правил князь Мешко I. Он принял крещение благодаря своей жене Добраве.","tr":"Хжэст Пóльски был в дзевéньчсэт шэщдзещё́нтым шýстым рóку. Втэ́ды панóвал кщё́нжэ Мéшко Пéрвши. Пшы́ёл хжэст дзéньки свóей жóне Добрáве.","mn":"Мешко — созвучно «мешок»: князь несёт мешок крестиков к купели. Рифма: «В девятьсот шестьдесят шесть — крест у Польши есть».","why":"966 год и Мешко I — ключевая дата начала польской государственности и христианства, спрашивают часто.","p":0},"og_hymn_nazwa":{"c":"ogolne","qru":"Как называется польский гимн и кто написал его слова?","qpl":"Jak nazywa się hymn Polski i kto napisał słowa?","apl":"Hymn Polski nazywa się Mazurek Dąbrowskiego. Słowa napisał Józef Wybicki w 1797 roku dla Legionów Polskich we Włoszech. Oficjalnym hymnem jest od 1927 roku.","aru":"Польский гимн называется «Мазурка Домбровского». Слова написал Юзеф Выбицкий в 1797 году для Польских легионов в Италии. Официальным гимном он является с 1927 года.","tr":"Хымн Пóльски назы́ва ще Мазýрэк Домбрóвскего. Слóва напи́сал Ю́зэф Выби́цки в ты́щёнц щедэ́мсэт дзевеньдзещё́нтым щю́дмым рóку для Легё́нув Пóльских вэ Влóшэх. Офицья́льным хы́мнэм ест од ты́щёнц дзевéньчсэт двадзéстэго щю́дмэго рóку.","mn":"Домбровский танцует мазурку, а Выбицкий ВЫБИВАЕТ на барабане слова гимна.","why":"Название гимна и автор слов — обязательный вопрос про символы. Гимн с 1927 года.","p":0},"og_hymn_pierwsza_linia":{"c":"ogolne","qru":"Какая первая строка польского гимна?","qpl":"Jakie są pierwsze słowa hymnu Polski?","apl":"Pierwsze słowa hymnu to: Jeszcze Polska nie zginęła, kiedy my żyjemy.","aru":"Первая строка гимна: «Ещё Польша не погибла, пока мы живём».","tr":"Пéрвшэ слóва хы́мну то: Éщче Пóльска не згинэ́ўа, кéды мы жыéмы.","mn":"«Jeszcze Polska nie zginęła» — почти по-русски: «Ещё Польша не сгинула». Учи как одну фразу-заклинание.","why":"Первую строку гимна нередко просят процитировать наизусть — это знак знания символов.","p":0},"og_swieta_panstwowe":{"c":"ogolne","qru":"Какие главные государственные праздники в Польше?","qpl":"Jakie są najważniejsze święta państwowe w Polsce?","apl":"Najważniejsze święta państwowe to 3 maja, czyli Święto Konstytucji, i 11 listopada, czyli Święto Niepodległości. Dniami wolnymi są też Nowy Rok 1 stycznia, Święto Pracy 1 maja i Święto Wojska Polskiego 15 sierpnia.","aru":"Главные государственные праздники — 3 мая, День Конституции, и 11 ноября, День Независимости. Выходными являются также Новый год 1 января, День Труда 1 мая и День Войска Польского 15 августа.","tr":"Найважнéйшэ щвéнта паньствóвэ то тшэчéго мáя, чы́ли Щвéнто Конститýцьи, и едэнастэ́го листопáда, чы́ли Щвéнто Неподлэглóщчи. Дня́ми вóльными сон тэж Нóвы Рок пéрвшэго сты́чня, Щвéнто Прáцы пéрвшэго мáя и Щвéнто Вóйска Пóльскего пентнáстэго щéрпня.","mn":"11.11 — четыре единицы, как четыре штыка на параде Независимости. 3 мая — весной «расцветает» Конституция.","why":"3 мая и 11 ноября — главные национальные праздники, их спрашивают почти всегда; полезно назвать и остальные государственные выходные (1.01, 1.05, 15.08).","p":0},"og_swieta_katolickie":{"c":"ogolne","qru":"Какие главные католические праздники отмечают в Польше?","qpl":"Jakie są najważniejsze święta katolickie w Polsce?","apl":"Najważniejsze święta katolickie to Boże Narodzenie, 25 i 26 grudnia, oraz Wielkanoc z Poniedziałkiem Wielkanocnym. Dniami wolnymi są też Trzech Króli 6 stycznia, Zesłanie Ducha Świętego, Boże Ciało, Wniebowzięcie Matki Boskiej 15 sierpnia i Wszystkich Świętych 1 listopada. Od 2025 roku dniem wolnym jest także Wigilia, 24 grudnia.","aru":"Главные католические праздники — Рождество, 25 и 26 декабря, и Пасха с Пасхальным понедельником. Выходные также — Три Короля 6 января, Сошествие Святого Духа, Тела Господня (Боже Цяло), Успение Богородицы 15 августа и День Всех Святых 1 ноября. С 2025 года выходной также Сочельник, 24 декабря.","tr":"Найважнéйшэ щвéнта католи́цке то Бóжэ Народзéне, двадзéстэго пё́нтэго и двадзéстэго шýстэго грýдня, óраз Велькáноц з Понедзя́лкем Вельканóцным. Дня́ми вóльными сон тэж Тшэх Крýли шýстэго сты́чня, Зэслáне Дýха Щвентэ́го, Бóжэ Ця́ло, Внебовзéнче Мáтки Бóскей пентнáстэго щéрпня и Вшы́стких Щвéнтых пéрвшэго листопáда. Од два тыщё́нцэ двудзéстэго пё́нтэго рóку днем вóльным ест тáкжэ Виги́лия, двадзéстэго чвáртэго грýдня.","mn":"Каркас года: январь — Три Короля, весна — Пасха, лето — Боже Цяло и 15.08, осень — 1.11, зима — Вигилия и Рождество.","why":"Польша — преимущественно католическая страна; знание главных религиозных праздников ожидается на экзамене.","p":0},"og_dania_tradycyjne":{"c":"ogolne","qru":"Какие традиционные польские блюда вы знаете?","qpl":"Jakie znasz tradycyjne polskie dania?","apl":"Tradycyjne polskie dania to bigos, pierogi, żurek i kotlet schabowy.","aru":"Традиционные польские блюда — бигос, пероги (вареники), журек и котлет схабовый (свиная отбивная).","tr":"Традыцы́йнэ пóльске дáня то би́гос, перóги, жýрэк и кóтлет схабóвы.","mn":"","why":"Вопрос про национальную кухню частый; bigos и pierogi — самые узнаваемые блюда.","p":0},"og_desery":{"c":"ogolne","qru":"Какие традиционные польские десерты и пироги вы знаете?","qpl":"Jakie znasz tradycyjne polskie desery i ciasta?","apl":"Tradycyjne polskie słodycze to pączki, faworki, sernik, makowiec i szarlotka.","aru":"Традиционные польские сладости — пончики, фаворки (хворост), сырник, маковый рулет и шарлотка (яблочный пирог).","tr":"Традыцы́йнэ пóльске слоды́чэ то пóнчки, фавóрки, сéрник, макóвец и шарлóтка.","mn":"","why":"Sernik и makowiec — классика польской выпечки, особенно к праздникам; узнаваемый вопрос о кухне.","p":0},"og_noblisci":{"c":"ogolne","qru":"Каких польских нобелевских лауреатов вы знаете?","qpl":"Jakich polskich laureatów Nagrody Nobla znasz?","apl":"Polscy nobliści to Maria Skłodowska-Curie, a w literaturze Henryk Sienkiewicz, Władysław Reymont, Czesław Miłosz, Wisława Szymborska i Olga Tokarczuk. Pokojową Nagrodę Nobla dostał Lech Wałęsa.","aru":"Польские нобелевские лауреаты — Мария Склодовская-Кюри, а в литературе — Генрик Сенкевич, Владислав Реймонт, Чеслав Милош, Вислава Шимборская и Ольга Токарчук. Нобелевскую премию мира получил Лех Валенса.","tr":"Пóльсцы нобли́щчи то Мáря Склодóвска-Кюри́, а в литэратýжэ Хéнрык Щенкéвич, Влады́слав Рэ́ймонт, Чéслав Ми́лош, Висўáва Шымбóрска и Óльга Токáрчук. Покоё́вон Нагрóдэ Нóбла дóстал Лэх Ваўэ́нса.","mn":"Наука — Склодовская, мир — Валенса, литература — пятёрка: Сенкевич, Реймонт, Милош, Шимборская, Токарчук («Се-Ре-Ми-Ши-То»).","why":"Польша гордится своими нобелевскими лауреатами; Склодовская-Кюри (дважды) — самый известный пример.","p":0},"og_zubr":{"c":"ogolne","qru":"Какое животное является символом Беловежской пущи?","qpl":"Jakie zwierzę jest symbolem Puszczy Białowieskiej?","apl":"Symbolem Puszczy Białowieskiej jest żubr. To największe dzikie zwierzę w Polsce.","aru":"Символ Беловежской пущи — зубр. Это самое крупное дикое животное в Польше.","tr":"Сымбóлем Пýшчы Бялове́скей ест жубр. То найвéнкшэ дзи́ке звéжэ в Пóльсце.","mn":"","why":"Зубр и Беловежская пуща — известный природный символ Польши (объект ЮНЕСКО).","p":0},"og_kompozytorzy":{"c":"ogolne","qru":"Каких известных польских композиторов вы знаете?","qpl":"Jakich znasz znanych polskich kompozytorów?","apl":"Najbardziej znany polski kompozytor to Fryderyk Chopin. Znani są też Stanisław Moniuszko i Krzysztof Penderecki.","aru":"Самый известный польский композитор — Фридерик Шопен. Известны также Станислав Монюшко и Кшиштоф Пендерецкий.","tr":"Найбáрдзей знáны пóльски композы́тор то Фрыдэ́рык Шóпэн. Знáни сон тэж Станислáв Моню́шко и Кшы́штоф Пэндэрэ́цки.","mn":"Монюшко — «на ушко»: шепчет оперу на ушко. Пендерецкий даёт музыке «пенделя». Шопена и так знаешь.","why":"Шопен — национальная гордость и культурный символ; вопрос о композиторах распространён.","p":0},"og_rezyserzy":{"c":"ogolne","qru":"Каких известных польских режиссёров вы знаете?","qpl":"Jakich znasz znanych polskich reżyserów?","apl":"Znani polscy reżyserzy to Andrzej Wajda, Krzysztof Kieślowski i Roman Polański.","aru":"Известные польские режиссёры — Анджей Вайда, Кшиштоф Кесьлёвский и Роман Полански.","tr":"Знáни пóльсцы рэжысéжы то А́нджей Вáйда, Кшы́штоф Кещлёвски и Рóман Полáньски.","mn":"ВКП — «Великое Кино Польши»: Вайда, Кесьлёвский, Полански.","why":"Польское кино известно в мире; Вайда — лауреат почётного «Оскара», частый вопрос о культуре.","p":0},"og_smok_wawelski":{"c":"ogolne","qru":"Где живёт Вавельский дракон?","qpl":"Gdzie mieszka smok wawelski?","apl":"Smok wawelski mieszka w Krakowie, w Smoczej Jamie pod Wawelem, nad Wisłą. Według legendy pokonał go szewczyk Skuba.","aru":"Вавельский дракон живёт в Кракове, в Смочей Яме (Драконьей пещере) под Вавелем, у Вислы. По легенде его победил сапожник Скуба.","tr":"Смок вавéльски мéшка в Крáкове, в Смóчэй Я́ме под Вáвэлем, над Ви́слон. Вэ́длуг легéнды покóнал го шэ́вчык Скýба.","mn":"","why":"Легенда о Вавельском драконе — известный краковский символ и часть народной культуры.","p":0},"og_tlusty_czwartek":{"c":"ogolne","qru":"Что едят в Жирный четверг (Tłusty Czwartek)?","qpl":"Co je się w tłusty czwartek?","apl":"W tłusty czwartek je się pączki i faworki, czyli chrust. To ostatni czwartek karnawału przed wielkim postem.","aru":"В Жирный четверг едят пончики (пончки) и хворост (фаворки). Это последний четверг карнавала перед Великим постом.","tr":"В тлýсты чвáртэк е се пóнчки и фавóрки, чы́ли хруст. То остáтни чвáртэк карнавáлу пшэд вéльким пóстэм.","mn":"","why":"Tłusty czwartek — популярная традиция перед Великим постом, поляки едят пончики; типичный вопрос.","p":0},"og_danie_polskie":{"c":"ogolne","qru":"Какое блюдо является традиционно польским?","qpl":"Które danie jest tradycyjnie polskie?","apl":"Tradycyjnie polskie danie to bigos. Hot dog czy solanka to nie są polskie dania.","aru":"Традиционно польское блюдо — бигос. Хот-дог или солянка не являются польскими блюдами.","tr":"Традыцы́йне пóльске дáне то би́гос. Хот-дог чы соля́нка то не сон пóльске дáня.","mn":"","why":"Это вопрос-ловушка: важно выбрать именно польское блюдо (bigos), а не иностранное.","p":0},"og_wszystkich_swietych":{"c":"ogolne","qru":"Какой праздник отмечают 1 ноября?","qpl":"Jakie święto obchodzi się 1 listopada?","apl":"1 listopada obchodzi się Wszystkich Świętych. Ludzie odwiedzają groby i zapalają znicze.","aru":"1 ноября отмечают День всех святых. Люди посещают могилы и зажигают лампадки (свечи).","tr":"Пéрвшэго листопáда обхóдзи се Вшы́стких Щвéнтых. Лю́дзе одвéдзаён грóбы и запáляён зни́че.","mn":"","why":"1 ноября — важный день памяти; традиция посещать кладбища и зажигать лампады очень характерна.","p":0},"og_pisarze":{"c":"ogolne","qru":"Каких известных польских писателей и поэтов вы знаете?","qpl":"Jakich znasz znanych polskich pisarzy i poetów?","apl":"Znani polscy pisarze i poeci to Adam Mickiewicz, Henryk Sienkiewicz i Juliusz Słowacki.","aru":"Известные польские писатели и поэты — Адам Мицкевич, Генрик Сенкевич и Юлиуш Словацкий.","tr":"Знáни пóльсцы писáжы и поэ́ци то А́дам Мицкéвич, Хéнрык Шенкéвич и Ю́лиуш Слова́цки.","mn":"Два «-вича» плюс Словацкий: Мицкевич, Сенкевич + Словацкий (фамилия сама про «слова»).","why":"Мицкевич — главный национальный поэт; вопрос о литературе встречается часто.","p":0},"og_tradycje":{"c":"ogolne","qru":"Какие характерные польские традиции вы знаете?","qpl":"Jakie znasz charakterystyczne polskie tradycje?","apl":"Polskie tradycje to na przykład święconka, czyli święcenie pokarmów na Wielkanoc, oraz śmigus-dyngus, czyli oblewanie się wodą w lany poniedziałek. Znane są też Prima Aprilis, topienie Marzanny w pierwszy dzień wiosny i noc świętojańska.","aru":"Польские традиции — например, свенцонка (освящение еды на Пасху) и смигус-дынгус (обливание водой в «мокрый понедельник»). Известны также Прима Априлис (1 апреля), утопление Мажанны в первый день весны и ночь святого Яна.","tr":"Пóльске трады́цье то на пшы́клад щвенцóнка, чы́ли щвенцéне покáрмув на Велькáноц, óраз щми́гус-ды́нгус, чы́ли облéване се водóн в ля́ны понедзя́лэк. Знáнэ сон тэж При́ма Апри́лис, топéне Мажáнны в пéрвшы дзень вёсны и ноц щвентоя́ньска.","mn":"Свенцонка — «освящённая» корзинка. Смигус-дынгус — «смыть»: обливают водой в мокрый понедельник.","why":"Вопрос №71 канонического банка: ждут не только пасхальные обычаи (święconka, śmigus-dyngus), но и народные — Мажанну, Прима Априлис, ночь святого Яна.","p":0},"og_papiez":{"c":"ogolne","qru":"Какой известный поляк был Папой Римским?","qpl":"Który znany Polak był papieżem?","apl":"Papieżem był Jan Paweł II. Nazywał się Karol Wojtyła i był pierwszym papieżem Polakiem.","aru":"Папой Римским был Иоанн Павел II. Его звали Кароль Войтыла, и он был первым Папой-поляком.","tr":"Папéжэм был Ян Пáвэл Дрýги. Назы́вал се Кáроль Войты́ла и был пéрвшым папéжэм Поля́кем.","mn":"","why":"Иоанн Павел II — один из самых почитаемых поляков; вопрос о нём очень частый.","p":0},"og_kopernik":{"c":"ogolne","qru":"Кто создал гелиоцентрическую теорию?","qpl":"Kto stworzył teorię heliocentryczną?","apl":"Teorię heliocentryczną stworzył Mikołaj Kopernik. Był polskim astronomem.","aru":"Гелиоцентрическую теорию создал Николай Коперник. Он был польским астрономом.","tr":"Теóрье хэлиоцэнтры́чнон ствóжыл Микóлай Копéрник. Был пóльским астронóмэм.","mn":"","why":"Коперник — символ польской науки; «он остановил Солнце и сдвинул Землю» — известная фраза.","p":0},"og_dabrowski":{"c":"ogolne","qru":"Кто такой генерал Домбровский, о котором поётся в гимне?","qpl":"Kim był generał Dąbrowski, o którym śpiewamy w hymnie?","apl":"Jan Henryk Dąbrowski to polski generał. W 1797 roku stworzył Legiony Polskie we Włoszech. To o nim śpiewamy w hymnie Polski.","aru":"Ян Хенрик Домбровский — польский генерал. В 1797 году он создал Польские легионы в Италии. Именно о нём поётся в гимне Польши.","tr":"Ян Хэ́нрык Домбрóвски то пóльски генэрáл. В ты́щёнц щедэ́мсэт дзевеньдзещё́нтым щю́дмым рóку ствóжыл Легё́ны Пóльске вэ Влóшэх. То о ним щпевáмы в хы́мне Пóльски.","mn":"Гимн — мазурка ДЛЯ Домбровского: генерал ведёт легионы «z ziemi włoskiej do Polski» — из Италии в Польшу.","why":"Кластер гимна: после вопроса о названии гимна консулы часто уточняют, кто такой Домбровский и что за легионы.","p":0},"og_dzien_flagi":{"c":"ogolne","qru":"Что отмечают в Польше 2 мая?","qpl":"Co obchodzi się w Polsce 2 maja?","apl":"2 maja obchodzimy Dzień Flagi Rzeczypospolitej Polskiej oraz Dzień Polonii i Polaków za Granicą. To nie jest dzień wolny od pracy. Polacy wywieszają wtedy biało-czerwone flagi.","aru":"2 мая отмечаем День флага Республики Польша, а также День Полонии и поляков за границей. Это не выходной день. Поляки вывешивают в этот день бело-красные флаги.","tr":"Другéго мáя обходзи́мы Дзень Фля́ги Жэчыпосполи́тэй Пóльскей óраз Дзень Полóнии и Поля́кув за Грани́цон. То не ест дзень вóльны од прáцы. Поля́цы вывешáён втэ́ды бя́ло-чэрвóнэ фля́ги.","mn":"Между 1 и 3 мая флаг «сшивает» майские праздники. Полония — поляки за границей, то есть про тебя самого.","why":"2 мая стоит между госпраздниками 1 и 3 мая — любимый уточняющий вопрос; День Полонии напрямую связан с темой Карты Поляка, знать его обязательно.","p":0},"og_hymn_taraban":{"c":"ogolne","qru":"Какой инструмент упоминается в польском гимне?","qpl":"Jaki instrument jest wspomniany w hymnie Polski?","apl":"W hymnie wspomniany jest taraban, czyli duży wojskowy bęben. Ojciec mówi do córki Basi, że słychać, jak nasi biją w tarabany.","aru":"В гимне упоминается тарабан, то есть большой военный барабан. Отец говорит дочери Басе, что слышно, как наши бьют в тарабаны.","tr":"В хы́мне вспомня́ны ест тарáбан, чы́ли дýжы войскóвы бэ́мбэн. Óйчец мýви до цýрки Бáщи, жэ слы́хачь, як нáщи би́ён в тарабáны.","mn":"Тарабан — от «тарабанить»: отец с Басей слышат, как наши бьют в тарабаны.","why":"Вопрос №9 канонического банка: после названия гимна консул может уточнить, что за инструмент в нём звучит.","p":0},"og_hymn_muzeum":{"c":"ogolne","qru":"Где находится Музей государственного гимна?","qpl":"Gdzie znajduje się Muzeum Hymnu Narodowego?","apl":"Muzeum Hymnu Narodowego znajduje się w Będominie na Kaszubach. To dworek, w którym urodził się Józef Wybicki. Było to pierwsze muzeum hymnu na świecie.","aru":"Музей государственного гимна находится в Бендомине в Кашубии. Это усадьба, в которой родился Юзеф Выбицкий. Это был первый музей гимна в мире.","tr":"Музэ́ум Хы́мну Народовэ́го знайдýе ще в Бэндоми́не на Кашýбах. То двóрэк, в ктóрым урóдзил ще Ю́зэф Выби́цки. Бы́ло то пéрвшэ музэ́ум хы́мну на щвéче.","mn":"Где родился автор гимна — там гимн и «живёт»: дом Выбицкого в Бендомине стал музеем.","why":"Вопрос №95 канонического банка — завершение кластера про гимн: Бендомин — родовая усадьба Выбицких, филиал Национального музея в Гданьске.","p":0},"his_pierwszy_krol":{"c":"historia","qru":"Кто был первым королём Польши?","qpl":"Kto był pierwszym królem Polski?","apl":"Pierwszym królem Polski był Bolesław Chrobry. Został koronowany w 1025 roku.","aru":"Первым королём Польши был Болеслав Храбрый. Он был коронован в 1025 году.","tr":"Пе́рвшим кру́лем Пóльски быў Болéслав Хрóбры. Зостáў коронóваны в ты́сёнц два́дзешча пёнтым рóку.","mn":"Рифма: «Тысяча двадцать пять — Храбрый корону смог взять». Храбрый — первым осмелился стать королём.","why":"Болеслав I Храбрый — первый коронованный король Польши (коронация 1025). Его отец Мешко I был первым историческим правителем, но носил титул князя, а не короля.","p":0},"his_mieszko_i":{"c":"historia","qru":"Кто был первым историческим правителем Польши?","qpl":"Kto był pierwszym historycznym władcą Polski?","apl":"Pierwszym historycznym władcą Polski był Mieszko I. Był księciem, a w 966 roku przyjął chrzest. Jego żoną była Dobrawa, czeska księżniczka.","aru":"Первым историческим правителем Польши был Мешко I. Он был князем, а в 966 году принял крещение. Его женой была Добрава, чешская княжна.","tr":"Пе́рвшим хисторы́чным влáдцон Пóльски быў Мéшко Пéрвши. Быў кщóнжэнцем, а в дзевéнцьсэт шесьдзешóнт шóстым рóку пшиёнў хшчест. Егó жóнон былá Добрáва, чэ́ска кщенжни́чка.","mn":"Мешко — «мешок»: первый правитель принёс Польше «мешок» христианства (крещение 966).","why":"Мешко I — первый исторический правитель Польши, но он был князем, а не королём. Крещение Польши в 966 году считается началом польской государственности.","p":0},"his_testament_krzywoustego":{"c":"historia","qru":"Что такое статут (завещание) Болеслава Кривоустого 1138 года?","qpl":"Czym był statut (testament) Bolesława Krzywoustego z 1138 roku?","apl":"To dokument z 1138 roku, który podzielił Polskę między synów Bolesława Krzywoustego. Zaczęło się wtedy rozbicie dzielnicowe.","aru":"Это документ 1138 года, который разделил Польшу между сыновьями Болеслава Кривоустого. Тогда началась феодальная раздробленность.","tr":"То докýмент з ты́сёнц сто тшидзéсте óсмэго рóку, ктýры подзéлиў Пóльскен мéндзы сы́нув Болéслава Кшивоýстэго. Заче́нло щен вте́ды розби́це дзельницóвэ.","mn":"Кривоустый «криво» поделил страну между сыновьями — началась раздробленность. Рифма: «Тысяча сто тридцать восемь — Польшу на куски разносим».","why":"Статут Болеслава Кривоустого (1138) разделил страну между его сыновьями и положил начало периоду феодальной раздробленности (rozbicie dzielnicowe).","p":0},"his_popiel":{"c":"historia","qru":"О чём легенда о короле Попеле?","qpl":"O czym jest legenda o królu Popielu?","apl":"Według legendy zły król Popiel został zjedzony przez myszy w wieży w Kruszwicy. Po nim władzę objęła dynastia Piastów.","aru":"По легенде злого короля Попеля съели мыши в башне в Крушвице. После него власть перешла к династии Пястов.","tr":"Ведýг легéнды злы крýль Пóпель зостáў зъéдзоны пшез мы́ши в вéжи в Крушви́цы. По ним влáдзэн объéнла дынáстья Пя́стув.","mn":"","why":"Легенда о Попеле — польская легенда о жестоком князе, которого, по преданию, в башне в Крушвице съели мыши. После него к власти пришли Пясты.","p":0},"his_piast_kolodziej":{"c":"historia","qru":"Кто такой Пяст Колодей (Piast Kołodziej)?","qpl":"Kim był Piast Kołodziej?","apl":"Piast Kołodziej to legendarny przodek dynastii Piastów. Według legendy był prostym rolnikiem i kołodziejem.","aru":"Пяст Колодей — легендарный родоначальник династии Пястов. По легенде он был простым земледельцем и колесником.","tr":"Пяст Колóдзей то легендáрны пшóдек дынáстьи Пя́стув. Ведýг легéнды быў прóстым рольни́кем и колóдзеем.","mn":"Колодей — «колесо делай»: простой колесник, с чьего колеса «покатилась» династия Пястов.","why":"Пяст Колодей (колесник) — легендарный основатель первой польской династии Пястов, к которой принадлежали Мешко I и Болеслав Храбрый.","p":0},"his_jan_matejko":{"c":"historia","qru":"Кто такой Ян Матейко?","qpl":"Kim był Jan Matejko?","apl":"Jan Matejko był polskim malarzem. Malował wielkie obrazy historyczne, na przykład „Bitwę pod Grunwaldem”.","aru":"Ян Матейко был польским художником. Он писал большие исторические полотна, например «Битву под Грюнвальдом».","tr":"Ян Матéйко быў пóльским малáжэм. Малóваў вéлькье обрáзы хисторы́чнэ, на пшиклáд „Би́твэн под Грунвáльдэм”.","mn":"Матейко — «матёрый»: малюет матёрые исторические полотна, «Грюнвальд» размером со стену.","why":"Ян Матейко (1838–1893) — крупнейший польский исторический живописец. Его картины «Битва под Грюнвальдом», «Прусская дань» и другие формируют визуальный образ польской истории.","p":0},"his_kopernik":{"c":"historia","qru":"Кто такой Николай Коперник?","qpl":"Kim był Mikołaj Kopernik?","apl":"Mikołaj Kopernik był polskim astronomem. Urodził się w Toruniu. Powiedział, że to Ziemia krąży wokół Słońca, a jego najsłynniejsze dzieło to „O obrotach sfer niebieskich”.","aru":"Николай Коперник был польским астрономом. Он родился в Торуне. Он утверждал, что Земля вращается вокруг Солнца, а его самый знаменитый труд — «О вращении небесных сфер».","tr":"Микóлай Копéрник быў пóльским астронóмэм. Урóдзиў щен в Торýню. Поведзáў, жэ то Зéмя крóнжи вокýў Слóньца, а егó найслыннéйше дзéло то „О обрóтах сфэр небéских”.","mn":"","why":"Николай Коперник (1473–1543) — польский астроном, автор гелиоцентрической теории (Земля и планеты вращаются вокруг Солнца), изложенной в труде «De revolutionibus orbium coelestium».","p":0},"his_drewniana_murowana":{"c":"historia","qru":"О ком говорят: «Застал Польшу деревянной, а оставил каменной»?","qpl":"O kim mówi się: „Zastał Polskę drewnianą, a zostawił murowaną”?","apl":"Tak mówi się o Kazimierzu Wielkim. Zbudował dużo murowanych zamków i miast.","aru":"Так говорят о Казимире Великом. Он построил много каменных замков и городов.","tr":"Так мýви щен о Казьмéжу Вéлькем. Збудóваў дýжо мурóваных зáмкув и мяст.","mn":"Казимир — «камень + мир»: принял деревянную Польшу, оставил каменную.","why":"Поговорка «Zastał Polskę drewnianą, a zostawił murowaną» относится к Казимиру III Великому, при котором в Польше развернулось масштабное каменное строительство.","p":0},"his_kazimierz_wielki":{"c":"historia","qru":"Чем известен король Казимир III Великий?","qpl":"Z czego znany jest król Kazimierz III Wielki?","apl":"Kazimierz Wielki był wielkim reformatorem. Wydał ważne ustawy i zbudował wiele zamków i miast. Założył pierwszy polski uniwersytet w Krakowie i był ostatnim królem z dynastii Piastów.","aru":"Казимир Великий был великим реформатором. Он издал важные законы и построил много замков и городов. Он основал первый польский университет в Кракове и был последним королём из династии Пястов.","tr":"Казьмéж Вéльки быў вéльким рэформáторэм. Вы́даў вáжнэ устáвы и збудóваў вéле зáмкув и мяст. Залóжиў пéрвши пóльски унивэрсы́тэт в Крáкове и быў остáтним крýлем з дынáстьи Пя́стув.","mn":"Казимир — «камень + мир»: каменные замки и мир по новым законам (Уставам).","why":"Казимир III Великий (правил 1333–1370) — последний король из династии Пястов, провёл правовые реформы (Вислицкие и Петрковские уставы), укрепил государство и основал университет в Кракове.","p":0},"his_bitwa_plowce":{"c":"historia","qru":"Что произошло в битве под Пловцами в 1331 году?","qpl":"Co się stało w bitwie pod Płowcami w 1331 roku?","apl":"W 1331 roku Polacy walczyli pod Płowcami z Krzyżakami. Dowodził nimi król Władysław Łokietek. Bitwa nie była rozstrzygnięta, ale zatrzymała Krzyżaków.","aru":"В 1331 году поляки сражались под Пловцами с крестоносцами. Ими командовал король Владислав Локоток. Битва не принесла решающей победы, но остановила крестоносцев.","tr":"В ты́сёнц тши́ста тшидзéстым пе́рвшим рóку Поля́цы вальчы́ли под Плóвцами з Кшижáками. Довóдзиў ни́ми круль Влады́слав Локéтэк. Би́тва не бы́ла розстшыгнéнта, áле затшимáла Кшижáкув.","mn":"1331 — цифры-зеркало (13|31): два войска стоят друг против друга — ничья. Но маленький Локоток («с локоток») сумел остановить крестоносцев.","why":"Пловцы (27 сентября 1331) — знаменитое сражение Владислава Локотка с Тевтонским орденом. Формально битва осталась нерешённой, но она остановила наступление ордена и показала, что крестоносцев можно побеждать.","p":0},"his_bitwa_grunwald":{"c":"historia","qru":"Что произошло в битве под Грюнвальдом в 1410 году?","qpl":"Co się stało w bitwie pod Grunwaldem w 1410 roku?","apl":"W 1410 roku wojska polsko-litewskie pokonały Zakon Krzyżacki. Dowodził nimi król Władysław Jagiełło.","aru":"В 1410 году польско-литовские войска разбили Тевтонский орден. Ими командовал король Владислав Ягайло.","tr":"В ты́сёнц чтэры́ста дзешóнтым рóку войскá польско-литéвске поконáли Зáкон Кшижáцки. Довóдзиў ни́ми крýль Влады́слав Ягéлло.","mn":"Рифма: «Тысяча четыреста десять — будем орден месить». Командовал Ягайло.","why":"Битва под Грюнвальдом (15 июля 1410) — одно из крупнейших сражений средневековой Европы; объединённые польско-литовские войска под командованием Владислава II Ягайло разгромили Тевтонский орден.","p":0},"his_warnenczyk":{"c":"historia","qru":"Как погиб король Владислав III Варненьчик?","qpl":"Jak zginął król Władysław III Warneńczyk?","apl":"Władysław III Warneńczyk zginął w 1444 roku w bitwie pod Warną. Walczył z Turkami.","aru":"Владислав III Варненьчик погиб в 1444 году в битве под Варной. Он сражался с турками.","tr":"Влады́слав Тшéчи Варнéньчик зги́нон в ты́сёнц чтэры́ста чтэрдзéсте чвáртым рóку в би́тве под Вáрнон. Вáльчиў з Тýрками.","mn":"Варненьчик = погиб под ВАРНОЙ — прозвище само подсказывает ответ. 1444: одинокая единица и три четвёрки — молодой король против рядов турок.","why":"Владислав III, король Польши и Венгрии, погиб 10 ноября 1444 года в битве под Варной с Османской империей; отсюда прозвище «Варненьчик».","p":0},"his_pierwszy_jagiellon":{"c":"historia","qru":"Кто был первым королём из династии Ягеллонов?","qpl":"Kto był pierwszym królem z dynastii Jagiellonów?","apl":"Pierwszym królem z dynastii Jagiellonów był Władysław II Jagiełło. Wcześniej był wielkim księciem litewskim. Został królem Polski w 1386 roku po ślubie z królową Jadwigą.","aru":"Первым королём из династии Ягеллонов был Владислав II Ягайло. Раньше он был великим князем литовским. Он стал королём Польши в 1386 году после свадьбы с королевой Ядвигой.","tr":"Пе́рвшим крýлем з дынáстьи Ягеллóнув быў Влады́слав Дрýги Ягéлло. Вчéщьней быў вéльким кщéньчем литéвским. Зостáў крýлем Пóльски в ты́сёнц тши́ста ощемдзешóнт шóстым рóку по щлю́бе з крулёвóн Ядви́гон.","mn":"Ягайло → ЯГеллоны: династия названа его именем — значит, он и есть первый.","why":"Владислав II Ягайло, великий князь литовский, стал королём Польши после женитьбы на Ядвиге (1386) и основал династию Ягеллонов.","p":0},"his_ostatni_jagiellon":{"c":"historia","qru":"Кто был последним королём из династии Ягеллонов?","qpl":"Kto był ostatnim królem z dynastii Jagiellonów?","apl":"Ostatnim królem z dynastii Jagiellonów był Zygmunt II August. Zmarł w 1572 roku. Za jego panowania zawarto unię lubelską w 1569 roku, która połączyła Polskę i Litwę w Rzeczpospolitą Obojga Narodów.","aru":"Последним королём из династии Ягеллонов был Зыгмунт II Август. Он умер в 1572 году. При его правлении в 1569 году была заключена Люблинская уния, которая объединила Польшу и Литву в Речь Посполитую Обоих Народов.","tr":"Остáтним крýлем з дынáстьи Ягеллóнув быў Зы́гмунт Дрýги Áугуст. Змáрў в ты́сёнц пеньчьсэт щéдемдзешóнт дрýгим рóку. За егó пановáня завáрто ýнье любэ́льскон в ты́сёнц пеньчьсэт шесьдзешóнт дзевёнтым рóку, ктýра полончы́ла Пóльскен и Литвэн в Жэчпосполи́тон Обóйга Нарóдув.","mn":"Август — последний месяц лета, Зыгмунт Август — последнее «лето» Ягеллонов. Рифма: «Пятнадцать семьдесят два — династия мертва».","why":"Сигизмунд II Август — последний Ягеллон по мужской линии, умер бездетным в 1572 году. При нём заключена Люблинская уния 1569 года, создавшая Речь Посполитую Обоих Народов; после его смерти началась эпоха выборных королей.","p":0},"his_uniwersytet_jagiellonski":{"c":"historia","qru":"Кто и когда основал Ягеллонский университет?","qpl":"Kto i kiedy założył Uniwersytet Jagielloński?","apl":"Uniwersytet w Krakowie założył król Kazimierz Wielki w 1364 roku. To najstarsza uczelnia w Polsce. W 1400 roku odnowił go król Władysław Jagiełło — stąd nazwa Jagielloński.","aru":"Университет в Кракове основал король Казимир Великий в 1364 году. Это старейший вуз в Польше. В 1400 году его обновил король Владислав Ягайло — отсюда название «Ягеллонский».","tr":"Унивэрсытéт в Крáкове залóжиў круль Кази́меж Вéльки в ты́сёнц тшы́ста шэщьдзещё́нтым чвáртым рóку. То найстáрша учéльня в Пóльсце. В ты́сёнц чтэрэхсэ́тным рóку однóвиў го круль Владислáв Ягéлло — стонд нáзва Ягеллóньски.","mn":"Казимир Великий строил из камня — построил и «каменную школу». Рифма: «Тринадцать шестьдесят четыре — старейший вуз в польском мире».","why":"Краковская академия основана Казимиром III Великим в 1364 году (вопрос №43 банка) — старейший университет Польши. В 1400 году обновлена Владиславом Ягайло на драгоценности королевы Ядвиги — отсюда имя «Ягеллонский».","p":0},"his_szczerbiec":{"c":"historia","qru":"Какие были польские коронационные регалии и что такое Щербец?","qpl":"Jakie były polskie insygnia koronacyjne i czym jest Szczerbiec?","apl":"Insygnia koronacyjne polskich królów to korona, berło, jabłko i miecz Szczerbiec. Szczerbiec to jedyny oryginał, który się zachował — koronowano nim królów od Władysława Łokietka. Dziś znajduje się na Wawelu w Krakowie.","aru":"Коронационные регалии польских королей — это корона, скипетр, держава и меч Щербец. Щербец — единственный сохранившийся оригинал, им короновали королей начиная с Владислава Локетка. Сегодня он находится на Вавеле в Кракове.","tr":"Инсы́гня коронацы́йнэ пóльских крýлюв то корóна, бэ́рло, я́пко и меч Щéрбец. Щéрбец то еды́ны орыгинáл, ктýры щен захóваў — коронóвано ним крýлюв од Владислáва Локéтка. Дзищ знáйдуе щен на Вáвелю в Крáкове.","mn":"Щербец — от «щербины»: меч с зазубриной. Из всех регалий уцелел он один: корона, скипетр и держава погибли, меч остался.","why":"Вопрос №41 канонического банка: регалии — корона, скипетр, держава и меч. Оригиналы вывезли и уничтожили пруссаки после разделов; уцелел только Щербец (коронации с Владислава Локетка, 1320), хранится в замке на Вавеле.","p":0},"his_konrad_mazowiecki":{"c":"historia","qru":"Кто привёл крестоносцев (Тевтонский орден) в Польшу?","qpl":"Kto sprowadził Krzyżaków do Polski?","apl":"Krzyżaków sprowadził książę Konrad Mazowiecki w 1226 roku. Chciał, żeby pomogli mu walczyć z Prusami.","aru":"Крестоносцев привёл князь Конрад Мазовецкий в 1226 году. Он хотел, чтобы они помогли ему воевать с пруссами.","tr":"Кшижáкув спровáдзиў кщóнжэ Кóнрад Мазовéцки в ты́сёнц двéщче двудзéстым шóстым рóку. Хчáу, жэбы помóгли му вáльчиць з Прýсами.","mn":"Конрад «намазал» Польше беду — позвал крестоносцев. Рифма: «Тысяча двести двадцать шесть — рыцари в Польше есть».","why":"Князь Конрад Мазовецкий пригласил Тевтонский орден (1226) для борьбы с языческими пруссами. Это решение оказалось роковым: орден создал собственное государство, ставшее врагом Польши.","p":0},"his_lajkonik":{"c":"historia","qru":"Что такое легенда о Лайконике (Lajkonik)?","qpl":"Czym jest legenda o Lajkoniku?","apl":"Lajkonik to człowiek przebrany za Tatara na drewnianym koniu. Według legendy przypomina zwycięstwo krakowian nad Tatarami w XIII wieku. Pochód Lajkonika odbywa się w Krakowie raz w roku, po Bożym Ciele.","aru":"Лайконик — это человек, переодетый татарином, на деревянном коне. По легенде он напоминает о победе краковян над татарами в XIII веке. Шествие Лайконика проходит в Кракове раз в году, после праздника Тела Господня.","tr":"Лáйконик то члóвек пшэбрáны за Татáра на дрэвня́ным кóню. Вэ́длуг легéнды пшипоми́на звычéньство кракóвян над Татáрами в тшынáстым вéку. Пóхуд Лайкони́ка одбы́ва ще в Крáкове раз в рóку, по Бóжым Чéле.","mn":"","why":"Лайконик есть в оглавлении канонического пособия (ответа в самом PDF нет — надо знать со стороны): краковская традиция, всадник в татарском наряде на деревянном коне, память о нашествиях татар XIII века.","p":0},"his_patroni_polski":{"c":"historia","qru":"Кто покровители (святые патроны) Польши?","qpl":"Kto jest patronem Polski?","apl":"Głównymi patronami Polski są święty Wojciech, święty Stanisław i Najświętsza Maryja Panna Królowa Polski. Patronem polskiej młodzieży jest święty Stanisław Kostka.","aru":"Главные святые покровители Польши — святой Войцех, святой Станислав и Пресвятая Дева Мария Королева Польши. Покровитель польской молодёжи — святой Станислав Костка.","tr":"Глýвными патрóнами Пóльски сон щéнты Вóйчех, щéнты Стани́слав и Найщéнтша Мáрыя Пáнна Крýлёва Пóльски. Патрóнэм пóльскей млодзéжы ест щéнты Стани́слав Кóстка.","mn":"","why":"Религия — важная часть польской идентичности, и вопрос о святых покровителях встречается на собеседовании. Главные патроны Польши: св. Войцех, св. Станислав и Дева Мария Королева Польши.","p":0},"his_sw_wojciech":{"c":"historia","qru":"Кто такой святой Войцех (św. Wojciech)?","qpl":"Kim był święty Wojciech?","apl":"Święty Wojciech był biskupem, misjonarzem i męczennikiem. Zginął w 997 roku podczas misji u pogańskich Prusów. Bolesław Chrobry wykupił jego ciało za tyle złota, ile ono ważyło, i pochował je w Gnieźnie.","aru":"Святой Войцех был епископом, миссионером и мучеником. Он погиб в 997 году во время миссии у язычников-пруссов. Болеслав Храбрый выкупил его тело за столько золота, сколько оно весило, и похоронил его в Гнезно.","tr":"Щéнты Вóйчех был бискýпэм, мисьёнáжэм и мэнчэнни́кем. Зги́нол в дзевеньчьсэ́т дзевеньдзещё́нтым щóдмым рóку пóдчас ми́сьи у погáньских Прýсув. Болéслав Хрóбры выкýпил éго чя́ло за ты́ле злóта, и́ле óно важы́ло, и похóвал е в Гнéзьне.","mn":"Войцех — «воин-чех»: пришёл из Чехии. Погиб в 997 — чуть не дожил до круглой тысячи. Тело выкупили золотом на вес — буквально «на вес золота»; могила в Гнезно — «гнезде» польской церкви.","why":"Вопрос №37 канонического банка: где и как погиб св. Войцех. Ключевые факты для ответа: миссия к пруссам, 997 год, тело выкуплено золотом по весу, похоронен в Гнезно; один из главных покровителей Польши.","p":0},"his_sw_jadwiga":{"c":"historia","qru":"Какие две святые Ядвиги есть в польской истории?","qpl":"Które dwie święte Jadwigi są w polskiej historii?","apl":"Są dwie: święta Jadwiga Śląska, księżna, oraz święta królowa Jadwiga Andegaweńska, którą koronowano na króla w 1384 roku. Królowa Jadwiga była żoną Władysława Jagiełły i oddała swoje klejnoty na odnowienie Akademii Krakowskiej.","aru":"Их две: святая Ядвига Силезская, княгиня, и святая королева Ядвига Анжуйская, которую короновали как короля в 1384 году. Королева Ядвига была женой Владислава Ягайло и отдала свои драгоценности на обновление Краковской академии.","tr":"Сон две: щéнта Ядви́га Щлóнска, кщéнжна, óраз щéнта крýлёва Ядви́га Андэгавéньска, ктýрон коронóвано на крýля в ты́сёнц тшы́ста ощемдзещё́нтым чвáртым рóку. Крýлёва Ядви́га бы́ла жóнон Владислáва Ягéллы и оддáла свóе клейнóты на одновéне Акадэ́мии Кракóвскей.","mn":"Две Ядвиги: Силезская — княгиня, Анжуйская — королева, которую короновали КАК КОРОЛЯ (женщина-король — сам по себе крючок).","why":"Ядвига Силезская (XIII в., канонизирована 1267) — княгиня, покровительница Силезии. Ядвига Анжуйская (XIV в., канонизирована в 1997 Иоанном Павлом II) — королева, коронованная как «король Польши» в 1384 году, жена Ягайло.","p":0},"his_potop":{"c":"historia","qru":"Что такое \"шведский потоп\" (potop szwedzki)?","qpl":"Co to był potop szwedzki?","apl":"Potop szwedzki to najazd Szwecji na Polskę w latach 1655–1660. Szwedzi zajęli prawie cały kraj, ale Polska w końcu wygrała.","aru":"Шведский потоп — это нашествие Швеции на Польшу в 1655–1660 годах. Шведы заняли почти всю страну, но Польша в итоге победила.","tr":"Пóтоп швэ́дзки то нáязд Швэ́цьи на Пóльскэ в ля́тах ты́сёнц шэщьсэ́т пеньдзещё́нт пеньчь до ты́сёнц шэщьсэ́т шэщьдзещё́нт. Швэ́дзи зае́ли прáве цáлы край, áле Пóльска в кóньцу выгрáла.","mn":"Потоп — швед «топит» Польшу. 1655: две пятёрки — как две волны; и длился потоп 5 лет (до 1660).","why":"Один из самых тяжёлых периодов в истории Речи Посполитой. Название «потоп» отражает масштаб нашествия, а популярным его сделал роман Генрика Сенкевича «Potop».","p":0},"his_kordecki":{"c":"historia","qru":"Кто такой Августин Кордецкий и чем знаменита оборона Ясной Горы?","qpl":"Kim był Augustyn Kordecki i czym była obrona Jasnej Góry?","apl":"Augustyn Kordecki był przeorem klasztoru na Jasnej Górze. W 1655 roku dowodził obroną klasztoru przed Szwedami. Obrona Jasnej Góry stała się symbolem oporu.","aru":"Августин Кордецкий был приором монастыря на Ясной Гуре. В 1655 году он руководил обороной монастыря от шведов. Оборона Ясной Гуры стала символом сопротивления.","tr":"Аугусты́н Кордэ́цки был пшэóрэм кля́штору на Я́сней Гýжэ. В ты́сёнц шэщьсэ́т пеньдзещё́нтым пё́нтым рóку довóдзил обрóнон кля́штору пшэд Швэ́дами. Обрóна Я́сней Гýры стáла ще сымбóлем опóру.","mn":"Кордецкий — «кордон»: монах стал кордоном для шведов на Ясной Гуре (1655).","why":"Ясна Гура (Ченстохова) — главная святыня Польши с иконой Чёрной Мадонны. Успешная оборона переломила настроение в войне со шведами.","p":0},"his_rozbiory":{"c":"historia","qru":"Когда были три раздела Речи Посполитой?","qpl":"Kiedy były trzy rozbiory Rzeczypospolitej?","apl":"Pierwszy rozbiór był w 1772 roku, drugi w 1793 roku, a trzeci w 1795 roku. Po trzecim rozbiorze Polska zniknęła z mapy Europy.","aru":"Первый раздел был в 1772 году, второй в 1793 году, а третий в 1795 году. После третьего раздела Польша исчезла с карты Европы.","tr":"Пе́рвши розбю́р был в ты́сёнц щедэмсэ́т щедэмдзещё́нтым дрýгим рóку, дрýги в ты́сёнц щедэмсэ́т дзевеньдзещё́нтым тшэ́чим, а тшэ́чи в ты́сёнц щедэмсэ́т дзевеньдзещё́нтым пё́нтым. По тшэ́чим розбё́жэ Пóльска зникнэ́ла з мáпы Эурóпы.","mn":"Лесенка хвостов: 72 — 93 — 95. Рифма: «Семьдесят два — Польша жива, девяносто три — треснула изнутри, девяносто пять — исчезла опять».","why":"После третьего раздела 1795 года Польша утратила независимость на 123 года, до 1918 года.","p":0},"his_rozbiory_panstwa":{"c":"historia","qru":"Какие страны участвовали в разделах Польши?","qpl":"Które państwa brały udział w rozbiorach Polski?","apl":"W rozbiorach Polski brały udział trzy państwa: Rosja, Prusy i Austria.","aru":"В разделах Польши участвовали три государства: Россия, Пруссия и Австрия.","tr":"В розбё́рах Пóльски брáлы ýдзял тши пáньства: Рóсья, Прýсы и Аýстрья.","mn":"","why":"Россия и Пруссия участвовали во всех трёх разделах, Австрия — в первом и третьем.","p":0},"his_poniatowski":{"c":"historia","qru":"Кто был последним королём Польши?","qpl":"Kto był ostatnim królem Polski?","apl":"Ostatnim królem Polski był Stanisław August Poniatowski. Panował w latach 1764–1795, do trzeciego rozbioru.","aru":"Последним королём Польши был Станислав Август Понятовский. Он правил в 1764–1795 годах, до третьего раздела.","tr":"Остáтним крýлем Пóльски был Стани́слав Áугуст Понятóвски. Панóвал в ля́тах ты́сёнц щедэмсэ́т шэщьдзещё́нт чтэ́ры до ты́сёнц щедэмсэ́т дзевеньдзещё́нт пеньчь, до тшэ́чего розбё́ру.","mn":"Понятовский — «понятой» при разделе собственной страны. Правил до 1795 — до третьего раздела (одна дата — два ответа).","why":"При нём была принята Конституция 3 мая 1791 года. После третьего раздела он отрёкся от престола.","p":0},"his_targowica":{"c":"historia","qru":"Что такое Тарговицкая конфедерация?","qpl":"Co to była konfederacja targowicka?","apl":"Konfederacja targowicka to spisek polskich magnatów z 1792 roku. Wezwali oni Rosję na pomoc przeciwko Konstytucji 3 maja.","aru":"Тарговицкая конфедерация — это заговор польских магнатов 1792 года. Они призвали Россию на помощь против Конституции 3 мая.","tr":"Конфэдэрáцья таргови́цка то спи́сэк пóльских магнáтув з ты́сёнц щедэмсэ́т дзевеньдзещё́нтэго дрýгего рóку. Вэзвáли óни Рóсье на пóмоц пшэци́вко Конституцы́и тшэ́чего мáя.","mn":"Тарговица — «торговцы»: магнаты «продали» реформы России в 1792 — за год до второго раздела.","why":"В Польше слово \"targowiczanin\" стало синонимом предателя. Конфедерация привела ко второму разделу страны.","p":0},"his_kosciuszko":{"c":"historia","qru":"Кто такой Тадеуш Костюшко и что такое восстание Костюшко?","qpl":"Kim był Tadeusz Kościuszko i czym była insurekcja kościuszkowska?","apl":"Tadeusz Kościuszko był polskim bohaterem narodowym. W 1794 roku poprowadził powstanie przeciwko Rosji i Prusom, zwane insurekcją kościuszkowską.","aru":"Тадеуш Костюшко был польским национальным героем. В 1794 году он возглавил восстание против России и Пруссии, называемое восстанием Костюшко.","tr":"Тадэ́уш Кощчю́шко был пóльским бохатэ́рэм народóвым. В ты́сёнц щедэмсэ́т дзевеньдзещё́нтым чвáртым рóку попровáдзил повстáне пшэци́вко Рóсьи и Прýсом, звáнэ инсурэ́кцьён кощчюшкóвскон.","mn":"Костюшко — «костёр»: в 1794 разжёг костёр восстания. Ступенька лесенки 91→95.","why":"Костюшко также участвовал в войне за независимость США. Известна битва под Рацлавицами и присяга на рынке в Кракове.","p":0},"his_konstytucja3maja":{"c":"historia","qru":"Что такое Конституция 3 мая 1791 года?","qpl":"Co to była Konstytucja 3 maja 1791 roku?","apl":"Konstytucja 3 maja to pierwsza konstytucja w Europie i druga na świecie. Uchwalono ją 3 maja 1791 roku, żeby zreformować państwo.","aru":"Конституция 3 мая — это первая конституция в Европе и вторая в мире. Её приняли 3 мая 1791 года, чтобы реформировать государство.","tr":"Конститýцья тшэчéго мáя то пéрвша конститýцья в Эурóпе и дрýга на щвéче. Ухвалóно йон тшэчéго мáя ты́сёнц щедэ́мсэт дзевеньчдзещёнтэ́го пéрвшэго рóку, жэ́бы зрэформóвачь пáньство.","mn":"Лесенка 91→95: Конституция 91, Тарговица 92, второй раздел 93, Костюшко 94, конец Польши 95. Пять лет — пять ступенек вниз.","why":"Первой в мире была Конституция США (1787). 3 мая — государственный праздник Польши.","p":0},"his_listopadowe":{"c":"historia","qru":"Что такое Ноябрьское восстание?","qpl":"Co to było powstanie listopadowe?","apl":"Powstanie listopadowe to zryw narodowy przeciwko Rosji w latach 1830–1831. Wybuchło w nocy z 29 na 30 listopada 1830 roku w Warszawie.","aru":"Ноябрьское восстание — это национальное выступление против России в 1830–1831 годах. Оно вспыхнуло в ночь с 29 на 30 ноября 1830 года в Варшаве.","tr":"Повстáне листопадóвэ то зрыв народóвы пшэци́вко Рóсьи в лáтах ты́сёнц ощéмсэт тшидзéщчи – ты́сёнц ощéмсэт тшидзéщчи éдэн. Выбýхло в нóцы з двудзестэ́го дзевёнтэ́го на тшидзестэ́го листопáда ты́сёнц ощéмсэт тшидзестэ́го рóку в Варшáве.","mn":"Listopad = ноябрь: «листопадовое» восстание. Порядок: месяцы идут назад (ноябрь → январь), годы вперёд (1830 → 1863).","why":"Восстание против Российской империи в Царстве Польском. Окончилось поражением, многие участники эмигрировали.","p":0},"his_styczniowe":{"c":"historia","qru":"Что такое Январское восстание?","qpl":"Co to było powstanie styczniowe?","apl":"Powstanie styczniowe to największy zryw narodowy przeciwko Rosji w latach 1863–1864. Było to powstanie partyzanckie.","aru":"Январское восстание — это крупнейшее национальное выступление против России в 1863–1864 годах. Это было партизанское восстание.","tr":"Повстáне стычнё́вэ то найвéнкши зрыв народóвы пшэци́вко Рóсьи в лáтах ты́сёнц ощéмсэт шэщьчдзéщёнт тши до ты́сёнц ощéмсэт шэщьчдзéщёнт чтэ́ры. Бы́ло то повстáне партызáнцке.","mn":"Styczeń = январь. 1863: «63 партизана» — война была партизанской. Крючок: Варшавское восстание 1944 длилось тоже 63 дня.","why":"Самое продолжительное польское восстание XIX века. После поражения усилилась русификация.","p":0},"his_nadniemnem":{"c":"historia","qru":"Кто написал роман \"Над Неманом\" (Nad Niemnem)?","qpl":"Kto napisał powieść \"Nad Niemnem\"?","apl":"Powieść \"Nad Niemnem\" napisała Eliza Orzeszkowa. Akcja powieści nawiązuje do powstania styczniowego.","aru":"Роман \"Над Неманом\" написала Элиза Ожешкова. Сюжет романа связан с Январским восстанием.","tr":"Пóвещчь \"Над Нéмнэм\" написáла Эли́за Ожэшкóва. Áкцья повéщчи навёнзýе до повстáня стычнёвэ́го.","mn":"Ожешкова — «орешек»: Элиза сидит над Неманом и грызёт орешки. Роман — «крепкий орешек» про Январское восстание.","why":"Один из важнейших польских реалистических романов (1888). Ожешкова — классик польской литературы XIX века.","p":0},"his_pantadeusz":{"c":"historia","qru":"Кто написал поэму \"Пан Тадеуш\"?","qpl":"Kto napisał \"Pana Tadeusza\"?","apl":"\"Pana Tadeusza\" napisał Adam Mickiewicz. To narodowa epopeja Polski, wydana w 1834 roku.","aru":"\"Пана Тадеуша\" написал Адам Мицкевич. Это национальная эпопея Польши, изданная в 1834 году.","tr":"\"Пáна Тадэýша\" написáл Áдам Мицкéвич. То народóва эпопэ́я Пóльски, выдáна в ты́сёнц ощéмсэт тшидзéстым чвáртым рóку.","mn":"Главный поэт написал главную эпопею: Мицкевич = «Пан Тадеуш».","why":"Адам Мицкевич — величайший польский поэт-романтик. Поэма начинается словами \"Litwo! Ojczyzno moja!\".","p":0},"his_wieden1683":{"c":"historia","qru":"Что такое Венская битва 1683 года?","qpl":"Co to była bitwa pod Wiedniem w 1683 roku?","apl":"Bitwa pod Wiedniem to zwycięstwo nad Turkami w 1683 roku. Polskim wojskiem dowodził król Jan III Sobieski.","aru":"Венская битва — это победа над турками в 1683 году. Польским войском командовал король Ян III Собеский.","tr":"Би́тва под Вéднем то звычéньство над Тýрками в ты́сёнц шэ́щьчьсэт ощемдзещё́нтым тшэ́чим рóку. Пóльским вóйскем довóдзил круль Ян Тшэ́чи Собéски.","mn":"Рифма: «Шестнадцать восемьдесят три — турок под Веной потри». СОБеский — как верный пёс, отогнал турок от Вены.","why":"Также называется \"odsiecz wiedeńska\". Собеский остановил турецкое продвижение в Европу, его прозвали \"львом Лехистана\".","p":0},"his_sobieski":{"c":"historia","qru":"Кто такой Ян III Собеский?","qpl":"Kim był Jan III Sobieski?","apl":"Jan III Sobieski był królem Polski. Wygrał bitwę pod Wiedniem w 1683 roku przeciwko Turkom.","aru":"Ян III Собеский был королём Польши. Он выиграл Венскую битву в 1683 году против турок.","tr":"Ян Тшэ́чи Собéски был крýлем Пóльски. Вы́грал би́твэ под Вéднем в ты́сёнц шэ́щьчьсэт ощемдзещё́нтым тшэ́чим рóку пшэци́вко Тýркам.","mn":"Собеский = Вена 1683. Рифма: «Шестнадцать восемьдесят три — турок под Веной потри».","why":"Один из самых известных польских королей, прославленный полководец. Правил в 1674–1696 годах.","p":0},"his_bitwawarszawska1920":{"c":"historia","qru":"Что такое Варшавская битва 1920 года (Чудо на Висле)?","qpl":"Co to była Bitwa Warszawska 1920 roku, czyli Cud nad Wisłą?","apl":"Bitwa Warszawska to zwycięstwo Polski nad Rosją bolszewicką w sierpniu 1920 roku. Nazywa się ją Cudem nad Wisłą.","aru":"Варшавская битва — это победа Польши над большевистской Россией в августе 1920 года. Её называют Чудом на Висле.","tr":"Би́тва Варшáвска то звычéньство Пóльски над Рóсьён большэви́цкон в щéрпню ты́сёнц дзевéньчьсэт двудзестэ́го рóку. Назы́ва ще йон Цýдэм над Ви́слон.","mn":"«Чудо на Висле» — год читается как счёт: «девятнадцать-двадцать». Август 1920, сразу после Первой мировой.","why":"Битва спасла независимость Польши и остановила распространение большевизма на запад. Командовал Юзеф Пилсудский; в память о битве 15 августа отмечается праздник Войска Польского.","p":0},"his_powstaniewarszawskie1944":{"c":"historia","qru":"Что такое Варшавское восстание 1944 года?","qpl":"Co to było powstanie warszawskie 1944 roku?","apl":"Powstanie warszawskie to zryw przeciwko Niemcom. Wybuchło 1 sierpnia 1944 roku i trwało 63 dni. Zakończyło się klęską.","aru":"Варшавское восстание — это выступление против немцев. Оно вспыхнуло 1 августа 1944 года и длилось 63 дня. Закончилось поражением.","tr":"Повстáне варшáвске то зрыв пшэци́вко Нéмцом. Выбýхло пéрвшэго щéрпня ты́сёнц дзевéньчьсэт чтэрдзестэ́го чвáртэго рóку и трвáло шэщьчдзéщёнт тши дни. Законьчы́ло ще клéнскон.","mn":"1944, 1 августа. Длилось 63 дня — как год Январского восстания (1863). Двойной крючок.","why":"Организовано Армией Крайовой. Немцы разрушили Варшаву почти полностью. Не путать с восстанием в гетто 1943 года.","p":0},"his_solidarnosc":{"c":"historia","qru":"Что такое \"Солидарность\" (Solidarność)?","qpl":"Co to była Solidarność?","apl":"Solidarność to niezależny związek zawodowy, założony w 1980 roku w Gdańsku. Jego przywódcą był Lech Wałęsa.","aru":"\"Солидарность\" — это независимый профсоюз, основанный в 1980 году в Гданьске. Его лидером был Лех Валенса.","tr":"Солидáрнощчь то незалéжны звё́нзэк заводóвы, заложóны в ты́сёнц дзевéньчьсэт ощемдзещё́нтым рóку в Гдáньску. Éго пшывýдцон был Лех Валэ́нса.","mn":"Круглый 1980: восьмидесятые в Польше начались с «Солидарности». Гданьск, верфь, Валенса.","why":"Первый независимый профсоюз в социалистическом блоке, возник после забастовок на верфи в Гданьске. Сыграл ключевую роль в падении коммунизма.","p":0},"his_stanwojenny":{"c":"historia","qru":"Что связано с 13 декабря 1981 года?","qpl":"Co wydarzyło się 13 grudnia 1981 roku?","apl":"13 grudnia 1981 roku generał Wojciech Jaruzelski wprowadził w Polsce stan wojenny. Skierowano go przeciwko Solidarności.","aru":"13 декабря 1981 года генерал Войцех Ярузельский ввёл в Польше военное положение. Оно было направлено против \"Солидарности\".","tr":"Тшинастэ́го грýдня ты́сёнц дзевéньчьсэт ощемдзещёнтэ́го пéрвшэго рóку гэнэ́рал Вóйчех Ярузэ́льски впровáдзил в Пóльсцэ стан воéнны. Скеровáно го пшэци́вко Солидарнóщчи.","mn":"13.12.1981 — «чёртова дюжина декабря»: Ярузельский принёс несчастливое военное положение.","why":"Военное положение длилось до 1983 года. Многие активисты \"Солидарности\" были интернированы.","p":0},"his_prezydenci":{"c":"historia","qru":"Назовите президентов Польши после 1989 года по порядку.","qpl":"Wymień prezydentów Polski po 1989 roku po kolei.","apl":"Prezydenci Polski po 1989 roku to: Wojciech Jaruzelski, Lech Wałęsa, Aleksander Kwaśniewski, Lech Kaczyński, Bronisław Komorowski, Andrzej Duda i obecnie Karol Nawrocki.","aru":"Президенты Польши после 1989 года: Войцех Ярузельский, Лех Валенса, Александр Квасьневский, Лех Качиньский, Бронислав Коморовский, Анджей Дуда и сейчас Кароль Навроцкий.","tr":"Прэзидэ́нчи Пóльски по ты́сёнц дзевéньчьсэт ощемдзещё́нтым дзевё́нтым рóку то: Вóйчех Ярузэ́льски, Лех Валэ́нса, Алексáндэр Квасьнéвски, Лех Качы́ньски, Брони́слав Коморóвски, Áнджэй Дýда и обэ́цне Кáроль Наврóцки.","mn":"Сначала переходный генерал Ярузельский, дальше фраза-якорь: «Вожак Квас Качал, Комар Дул Наверх» — Валенса, Квасьневский, Качиньский, Коморовский, Дуда, Навроцкий.","why":"На собеседовании часто просят назвать действующего президента: с августа 2025 года это Кароль Навроцкий. Ярузельский (1989–1990) — переходный президент, избранный парламентом; Лех Качиньский погиб в авиакатастрофе под Смоленском в 2010 году.","p":0},"his_walesa":{"c":"historia","qru":"Кто был первым президентом Польши после 1989 года?","qpl":"Kto był pierwszym prezydentem Polski po 1989 roku?","apl":"Pierwszym prezydentem Polski wybranym w wyborach powszechnych był Lech Wałęsa. Był też przywódcą Solidarności i laureatem Nagrody Nobla.","aru":"Первым президентом Польши, избранным на всеобщих выборах, был Лех Валенса. Он также был лидером \"Солидарности\" и лауреатом Нобелевской премии.","tr":"Пéрвшым прэзидэ́нтэм Пóльски выбрáным в выбóрах повшэ́хных был Лех Валэ́нса. Был тэж пшывýдцон Солидарнóщчи и лаурэáтэм Нагрóды Нóбля.","mn":"","why":"Валенса получил Нобелевскую премию мира в 1983 году. Был президентом в 1990–1995 годах.","p":0},"his_rzeczpospolita":{"c":"historia","qru":"Что такое I, II и III Речь Посполитая?","qpl":"Co to jest Pierwsza, Druga i Trzecia Rzeczpospolita?","apl":"Pierwsza Rzeczpospolita to państwo polsko-litewskie od unii lubelskiej w 1569 roku do rozbiorów w 1795 roku. Druga Rzeczpospolita to niepodległa Polska w latach 1918–1939. Trzecia Rzeczpospolita to Polska od 1989 roku do dziś.","aru":"Первая Речь Посполитая — польско-литовское государство от Люблинской унии 1569 года до разделов 1795 года. Вторая Речь Посполитая — независимая Польша 1918–1939 годов. Третья Речь Посполитая — Польша с 1989 года по сегодняшний день.","tr":"Пéрвша Жэчпосполи́та то пáньство пóльско-литéвске од ýнии любэ́льскей в ты́щёнц пе́ньчьсэт шэщчдзещёнтым дзевёнтым рóку до розбьóрув в ты́щёнц щедэ́мсэт дзевеньчдзещёнтым пёнтым рóку. Дрýга Жэчпосполи́та то неподлéгла Пóльска в ля́тах ты́щёнц дзеве́ньчсэт ощемнáщче — ты́щёнц дзеве́ньчсэт тши́дзещчи дзеве́ньчь. Тшэ́ча Жэчпосполи́та то Пóльска од ты́щёнц дзеве́ньчсэт ощемдзещёнтэго дзевёнтэго рóку до дзишь.","mn":"Три рождения: 1569 — уния (шляхетская республика), 1918 — независимость, 1989 — Круглый стол.","why":"Вопрос №25 канонического банка: экзаменатор проверяет, понимает ли кандидат периодизацию польской государственности, а не только отдельные даты.","p":0},"his_zjazd_gnieznienski":{"c":"historia","qru":"Что такое Гнезненский съезд 1000 года?","qpl":"Co to był zjazd gnieźnieński w roku 1000?","apl":"Zjazd gnieźnieński odbył się w roku tysięcznym. Cesarz Otton III przybył do grobu świętego Wojciecha w Gnieźnie i spotkał się z księciem Bolesławem Chrobrym. Powstało wtedy pierwsze polskie arcybiskupstwo — metropolia gnieźnieńska.","aru":"Гнезненский съезд состоялся в 1000 году. Император Оттон III прибыл к гробу святого Войцеха в Гнезно и встретился с князем Болеславом Храбрым. Тогда возникло первое польское архиепископство — Гнезненская митрополия.","tr":"Зъязд гнежьнéньски одбы́ў щен в рóку тыщéнчным. Цэ́саж Óттон Тшéчи пшибы́ў до грóбу щвéнтэго Вóйчеха в Гнéжьне и споткáў щен з кщóнжэнцем Болéславэм Хрóбрым. Повстáло вте́ды пе́рвше пóльске арцыбискýпство — метропóлья гнежьнéньска.","mn":"Круглая дата 1000 — «нулевой километр» польской церкви: император сам приехал в Гнезно к святому Войцеху.","why":"Вопрос №39 канонического банка: паломничество императора Оттона III к мощам св. Войцеха, встреча с Болеславом Храбрым и создание независимой польской церковной митрополии в Гнезно — веха становления государства.","p":0},"his_unia_krewo":{"c":"historia","qru":"Что такое Кревская уния 1385 года?","qpl":"Co to była unia w Krewie z 1385 roku?","apl":"Unia w Krewie została zawarta w 1385 roku. Wielki książę litewski Jagiełło obiecał przyjąć chrzest i ożenić się z królową Jadwigą. Tak zaczął się związek Polski z Litwą i dynastia Jagiellonów.","aru":"Кревская уния была заключена в 1385 году. Великий князь литовский Ягайло пообещал принять крещение и жениться на королеве Ядвиге. Так начался союз Польши с Литвой и династия Ягеллонов.","tr":"Ýнья в Крéве зостáла завáрта в ты́сёнц тши́ста ощемдзешóнт пёнтым рóку. Вéльки кщóнже литéвски Ягéлло обéцаў пши́ёнчь хшчест и ожэ́ничь щен з крулёвóн Ядви́гон. Так зачóнў щен звёнзэк Пóльски з Литвóн и дынáстья Ягеллóнув.","mn":"1385, Крево: «крещусь и женюсь» — Ягайло за корону пообещал крест и брак с Ядвигой.","why":"Кревская уния (14.08.1385) объясняет, как литовский князь стал польским королём: это начало польско-литовского союза и династии Ягеллонов — частый вопрос-связка перед Грюнвальдом и Люблинской унией.","p":0},"his_pilsudski":{"c":"historia","qru":"Кто такой Юзеф Пилсудский?","qpl":"Kim był Józef Piłsudski?","apl":"Józef Piłsudski to twórca Legionów Polskich i pierwszy marszałek Polski. 11 listopada 1918 roku objął władzę i Polska odzyskała niepodległość. W 1926 roku dokonał przewrotu majowego.","aru":"Юзеф Пилсудский — создатель Польских легионов и первый маршал Польши. 11 ноября 1918 года он принял власть, и Польша вернула независимость. В 1926 году он совершил Майский переворот.","tr":"Ю́зэф Пилсýдски то твýрца Легё́нув Пóльских и пéрвши маршáлэк Пóльски. Едэнастэ́го листопáда ты́сёнц дзевéньчьсэт ощемнастэ́го рóку óбйол влáдзэ и Пóльска одзыскáла неподлéглощчь. В ты́сёнц дзевéньчьсэт двудзéстым шýстым рóку докóнал пшэврóту маёвэ́го.","mn":"Пилсудский = 11.11.1918: усы маршала — как две единицы, «одиннадцатого одиннадцатого».","why":"Ключевая фигура возвращения независимости: 11 ноября 1918 года ему передали власть, отсюда главный госпраздник. Один из самых частых вопросов на собеседовании.","p":0},"his_wrzesien1939":{"c":"historia","qru":"Когда и как началась Вторая мировая война?","qpl":"Kiedy i jak wybuchła II wojna światowa?","apl":"Druga wojna światowa wybuchła 1 września 1939 roku, gdy Niemcy zaatakowały Polskę. Pierwsze strzały padły na Westerplatte w Gdańsku. 17 września Polskę zaatakował też Związek Radziecki.","aru":"Вторая мировая война началась 1 сентября 1939 года, когда Германия напала на Польшу. Первые выстрелы прозвучали на Вестерплатте в Гданьске. 17 сентября на Польшу напал также Советский Союз.","tr":"Дрýга вóйна щвятóва выбýхла пéрвшэго вжéщня ты́сёнц дзевéньчьсэт тшидзестэ́го дзевёнтэ́го рóку, гды Нéмцы заатаковáлы Пóльскэ. Пéрвшэ стшáлы пáдлы на Вэстэрплáттэ в Гдáньску. Щедэмнастэ́го вжéщня Пóльскэ заатакóвал тэж Звё́нзэк Радзéцки.","mn":"1.09 — удар с запада, 17.09 — удар с востока: Польша между двумя соседями.","why":"Базовый вопрос по XX веку: экзаменатор ждёт обе даты — 1 сентября (Германия, Westerplatte) и 17 сентября (СССР).","p":0},"his_getto1943":{"c":"historia","qru":"Что такое восстание в Варшавском гетто 1943 года?","qpl":"Co to było powstanie w getcie warszawskim?","apl":"Powstanie w getcie warszawskim wybuchło 19 kwietnia 1943 roku. Był to zryw Żydów przeciwko Niemcom podczas likwidacji getta. To inne wydarzenie niż powstanie warszawskie z 1944 roku.","aru":"Восстание в Варшавском гетто вспыхнуло 19 апреля 1943 года. Это было выступление евреев против немцев во время ликвидации гетто. Это другое событие, не Варшавское восстание 1944 года.","tr":"Повстáне в гéтче варшáвским выбýхло дзевентнастэ́го квéтня ты́сёнц дзевéньчьсэт чтэрдзестэ́го тшэчéго рóку. Был то зрыв Жы́дув пшэци́вко Нéмцом пóдчас ликвидáцьи гéтта. То и́ннэ выдажэ́не ниж повстáне варшáвске з ты́сёнц дзевéньчьсэт чтэрдзестэ́го чвáртэго рóку.","mn":"Гетто — на год раньше: 1943 → 1944. Сначала гетто, потом весь город.","why":"Частая ловушка на собеседовании: проверяют, отличает ли кандидат восстание в гетто (1943) от Варшавского восстания (1944).","p":0},"his_okraglystol":{"c":"historia","qru":"Что такое Круглый стол и выборы 4 июня 1989 года?","qpl":"Co to był Okrągły Stół i wybory 4 czerwca 1989 roku?","apl":"Okrągły Stół to rozmowy władzy komunistycznej z opozycją w 1989 roku. Dzięki nim 4 czerwca odbyły się częściowo wolne wybory. Był to początek końca komunizmu w Polsce.","aru":"Круглый стол — это переговоры коммунистической власти с оппозицией в 1989 году. Благодаря им 4 июня прошли частично свободные выборы. Это было начало конца коммунизма в Польше.","tr":"Окрóнглы Стул то розмóвы влáдзы комунисты́чнэй з опозы́цьён в ты́сёнц дзевéньчьсэт ощемдзещё́нтым дзевё́нтым рóку. Дзéнки ним чвáртэго чэ́рвца одбы́лы ще ченщчё́во вóльнэ выбóры. Был то почóнтэк кóньца комуни́зму в Пóльсцэ.","mn":"Круглый стол — без «главы стола»: власть и оппозиция договорились, а 4 июня урны решили всё.","why":"От выборов 4 июня 1989 года отсчитывают III Речь Посполитую; вопрос идёт в связке с «Солидарностью», Валенсой и stanem wojennym.","p":0},"geo_regiony":{"c":"geografia","qru":"Какие главные исторические регионы Польши вы знаете?","qpl":"Jakie są główne regiony historyczne Polski?","apl":"Najważniejsze regiony to Wielkopolska, Małopolska, Mazowsze, Pomorze, Śląsk, Warmia i Mazury oraz Podlasie.","aru":"Важнейшие регионы — это Великопольша, Малопольша, Мазовше, Поморье, Силезия, Вармия и Мазуры, а также Подляшье.","tr":"Найважнейше регьёны то Велькопольска, Малопольска, Мазовше, Поможе, Щлёнск, Вармя и Мазуры ораз Подляще.","mn":"","why":"Это историко-географические земли Польши. Силезия делится на Górny (Верхнюю) и Dolny (Нижнюю).","p":0},"geo_sasiedzi":{"c":"geografia","qru":"С какими странами граничит Польша?","qpl":"Z jakimi krajami graniczy Polska?","apl":"Polska graniczy z siedmioma krajami: z Niemcami, Czechami, Słowacją, Ukrainą, Białorusią, Litwą i Rosją.","aru":"Польша граничит с семью странами: с Германией, Чехией, Словакией, Украиной, Беларусью, Литвой и Россией.","tr":"Польска граничы з щедмёма краями: з Немцами, Чехами, Словацён, Украйнон, Бялорусён, Литвон и Росьён.","mn":"Иди по часовой с запада: Германия → Чехия → Словакия → Украина → Беларусь → Литва → Россия (Калининград). Семь стран.","why":"Семь соседей. С Россией граница проходит через Калининградскую область (obwód kaliningradzki).","p":0},"geo_morze":{"c":"geografia","qru":"Есть ли у Польши выход к морю? К какому?","qpl":"Czy Polska ma dostęp do morza? Do jakiego?","apl":"Tak, Polska ma dostęp do Morza Bałtyckiego. Wybrzeże leży na północy kraju.","aru":"Да, у Польши есть выход к Балтийскому морю. Побережье находится на севере страны.","tr":"Так, Польска ма доступ до Можа Балтыцкего. Выбжеже лежы на пулноцы краю.","mn":"","why":"Балтийское море на севере. На побережье — важные порты Гданьск, Гдыня, Щецин.","p":0},"geo_stolica":{"c":"geografia","qru":"Какая столица Польши и какие ещё крупные города вы знаете?","qpl":"Jaka jest stolica Polski i jakie inne duże miasta znasz?","apl":"Stolicą Polski jest Warszawa. Inne duże miasta to Kraków, Łódź, Wrocław, Poznań i Gdańsk.","aru":"Столица Польши — Варшава. Другие крупные города — Краков, Лодзь, Вроцлав, Познань и Гданьск.","tr":"Столицон Польски ест Варшава. Инне дуже мяста то Кракув, Лудзь, Вроцлав, Познань и Гданьск.","mn":"","why":"Варшава — крупнейший город и столица. Краков был столицей до 1596 года.","p":0},"geo_pierwsza_stolica":{"c":"geografia","qru":"Какой город был первой столицей Польши?","qpl":"Które miasto było pierwszą stolicą Polski?","apl":"Pierwszą stolicą Polski było Gniezno. Później stolicą był Kraków, a od 1596 roku Warszawa.","aru":"Первой столицей Польши было Гнезно. Позже столицей был Краков, а с 1596 года — Варшава.","tr":"Первшон столицон Польски было Гнезно. Пузней столицон был Кракув, а од тыщёнц пеньчсэт девеньчдзещёнт шустэго року Варшава.","mn":"Гнезно — «гнездо»: Польша вылупилась из Гнезна. Потом Краков, с 1596 — Варшава.","why":"Гнезно — колыбель польской государственности при Пястах. Перенос в Варшаву связан с королём Сигизмундом III.","p":0},"geo_wisla":{"c":"geografia","qru":"Какая самая длинная река в Польше?","qpl":"Jaka jest najdłuższa rzeka w Polsce?","apl":"Najdłuższą rzeką w Polsce jest Wisła. Drugą dużą rzeką jest Odra.","aru":"Самая длинная река в Польше — Висла. Вторая крупная река — Одра.","tr":"Найдлужшон жекон в Польсце ест Висла. Другон дужон жекон ест Одра.","mn":"","why":"Висла протекает через всю страну с юга на север; традиционно её длина — 1047 км, по новым измерениям GUS — 1022 км. Одра течёт на западе.","p":0},"geo_wisla_miasta":{"c":"geografia","qru":"Через какие города протекает Висла?","qpl":"Przez jakie miasta przepływa Wisła?","apl":"Wisła przepływa przez Kraków, Warszawę, Toruń i Gdańsk. W Gdańsku wpada do Morza Bałtyckiego.","aru":"Висла протекает через Краков, Варшаву, Торунь и Гданьск. В Гданьске она впадает в Балтийское море.","tr":"Висла пшеплива пшез Кракув, Варшавэн, Торунь и Гданьск. В Гданьску впада до Можа Балтыцкего.","mn":"По Висле с юга на север: Краков → Варшава → Торунь → Гданьск. «Каждый Вечер Торт Гданьский».","why":"Висла связывает юг и север страны и впадает в Балтику в районе Гданьска.","p":0},"geo_jeziora":{"c":"geografia","qru":"Какие самые большие озёра в Польше и где они?","qpl":"Jakie są największe jeziora w Polsce i gdzie się znajdują?","apl":"Największe jeziora to Śniardwy i Mamry. Leżą one na Mazurach, na północnym wschodzie kraju.","aru":"Самые большие озёра — Снярдвы и Мамры. Они находятся на Мазурах, на северо-востоке страны.","tr":"Найвенкше езёра то Щнярдвы и Мамры. Лежон оне на Мазурах, на пулноцным всходзе краю.","mn":"«МаМры на МаЗурах» — озеро и регион на «Ма». Рядом Снярдвы — самое большое.","why":"Мазуры — край тысячи озёр, популярное место отдыха. Снярдвы — крупнейшее озеро Польши.","p":0},"geo_gora":{"c":"geografia","qru":"Какая самая высокая гора в Польше?","qpl":"Jaki jest najwyższy szczyt w Polsce?","apl":"Najwyższym szczytem w Polsce są Rysy. Leżą w Tatrach na południu kraju. Główne pasma górskie to Karpaty i Sudety.","aru":"Самая высокая вершина в Польше — Рысы. Она находится в Татрах на юге страны. Главные горные цепи — Карпаты и Судеты.","tr":"Найвы́жшым шчы́тэм в По́льсце сон Ры́сы. Лежо́н в Тáтрах на полу́дню крáю. Глу́вне пáсма гу́рске то Карпáты и Судэ́ты.","mn":"На вершине Рысов сидит РЫСЬ — самая высокая точка (Татры).","why":"Рысы — 2499 м, в Татрах на границе со Словакией. Канонический вопрос №14 спрашивает и про горы вообще: Татры — часть Карпат, на юго-западе — Судеты.","p":0},"geo_parki":{"c":"geografia","qru":"Сколько национальных парков в Польше и какие вы знаете?","qpl":"Ile jest parków narodowych w Polsce i jakie znasz?","apl":"W Polsce są 23 parki narodowe. Najbardziej znane to Białowieski, Tatrzański i Biebrzański Park Narodowy.","aru":"В Польше 23 национальных парка. Самые известные — Беловежский, Татранский и Бебжанский.","tr":"В По́льсце сон двадзе́щча тши па́рки наро́довэ. Найба́рдзей зна́не то Бялове́ски, Татша́ньски и Бебжа́ньски Парк Наро́довы.","mn":"23 парка. Тройка «Б-Т-Б»: Беловежский, Татранский, Бебжанский.","why":"Беловежский парк известен зубрами и древним лесом, внесён в список ЮНЕСКО.","p":0},"geo_trojmiasto":{"c":"geografia","qru":"Какие крупные города на Балтийском побережье?","qpl":"Jakie duże miasta leżą nad Morzem Bałtyckim?","apl":"Nad Bałtykiem leżą Gdańsk, Gdynia i Sopot, które tworzą Trójmiasto. Dużym miastem jest też Szczecin.","aru":"На Балтике находятся Гданьск, Гдыня и Сопот, которые образуют Труймясто. Крупный город — также Щецин.","tr":"Над Балтыкем лежон Гданьск, Гдыня и Сопот, ктуре творжон Труймясто. Дужым мястэм ест теж Щецин.","mn":"Труймясто = «три города»: два «Г» и «С» — Гданьск, Гдыня, Сопот.","why":"Trójmiasto (Труймясто) — агломерация трёх городов: Гданьск, Гдыня, Сопот.","p":0},"geo_wawel":{"c":"geografia","qru":"Какие важнейшие средневековые сооружения Польши вы знаете?","qpl":"Jakie najważniejsze budowle średniowieczne w Polsce znasz?","apl":"W Krakowie to Wawel, czyli zamek królewski, i Sukiennice na Rynku Głównym. Ważny jest też zamek w Malborku — największy ceglany zamek na świecie, zbudowany przez Krzyżaków.","aru":"В Кракове это Вавель — королевский замок, и Сукеннице на Главном рынке. Важен также замок в Мальборке — крупнейший кирпичный замок в мире, построенный крестоносцами (Тевтонским орденом).","tr":"В Крако́ве то Ва́вель, чы́ли за́мэк круле́вски, и Сукенни́це на Ры́нку Глу́вным. Ва́жны ест теж за́мэк в Мальбо́рку — найве́нкшы цегля́ны за́мэк на щве́че, збудова́ны пшез Кшыжа́кув.","mn":"Три постройки: Вавель (король), Сукеннице (сукно/торговля), Мальборк (крестоносцы, кирпич).","why":"Канонический вопрос пособия (№57): Wawel и Sukiennice в Кракове плюс замок в Мальборке — столица Тевтонского ордена, объект ЮНЕСКО.","p":0},"geo_powierzchnia_ludnosc":{"c":"geografia","qru":"Какая площадь и население Польши?","qpl":"Jaka jest powierzchnia i liczba ludności Polski?","apl":"Polska ma powierzchnię około 312 700 kilometrów kwadratowych. Mieszka w niej ponad 37 milionów ludzi.","aru":"Площадь Польши — около 312 700 квадратных километров. В ней живёт более 37 миллионов человек.","tr":"Пóльска ма повéжхнен окóло тшы́ста дванáщче ты́щенцы щéдэмсэт киломэ́трув квадратóвых. Мéшка в ней пóнад тшыдзéщчи щéдэм мильóнув лю́дзи.","mn":"Обе цифры начинаются с тройки: ~312 тыс. км² и ~37 млн человек.","why":"По площади Польша — одна из крупнейших стран ЕС. По данным GUS, на конец 2025 года население — около 37,3 млн и постепенно снижается.","p":0},"geo_wojewodztwa":{"c":"geografia","qru":"Сколько воеводств в Польше?","qpl":"Ile województw jest w Polsce?","apl":"W Polsce jest szesnaście województw. Ten podział istnieje od 1999 roku. Znam na przykład województwo mazowieckie, małopolskie, śląskie, pomorskie i dolnośląskie.","aru":"В Польше шестнадцать воеводств. Это деление существует с 1999 года. Я знаю, например, Мазовецкое, Малопольское, Силезское, Поморское и Нижнесилезское воеводства.","tr":"В По́льсце ест шэсна́щче воеву́дзтв. Тэн подзя́л истне́е од ты́щёнц девеньчсэ́т девеньчдзещёнт девё́нтэго ро́ку. Знам на пшы́клад воеву́дзтво мазове́цке, малопо́льске, щлё́нске, помо́рске и дольнощлё́нске.","mn":"16 воеводств с 1999-го: реформа «под круглую дату» — к 2000 году страну поделили на 16.","why":"Канонические вопросы №86–87 пособия: административное деление. Достаточно уверенно назвать число 16, год 1999 и несколько примеров.","p":0},"geo_unesco":{"c":"geografia","qru":"Какие польские объекты входят в список ЮНЕСКО?","qpl":"Jakie polskie obiekty są na liście UNESCO?","apl":"Na liście UNESCO jest siedemnaście polskich obiektów. Na przykład Stare Miasto w Krakowie i w Warszawie, kopalnia soli w Wieliczce, zamek w Malborku, Toruń i Puszcza Białowieska.","aru":"В списке ЮНЕСКО семнадцать польских объектов. Например, Старый город в Кракове и в Варшаве, соляная шахта в Величке, замок в Мальборке, Торунь и Беловежская пуща.","tr":"На ли́щче ЮНЭ́СКО ест щедэмна́щче по́льских обье́ктув. На пшы́клад Ста́рэ Мя́сто в Кра́кове и в Варша́ве, копа́льня со́ли в Вели́чце, за́мэк в Мальбо́рку, То́рунь и Пу́шча Бялове́ска.","mn":"17 объектов: соль (Величка), замок (Мальборк), пряники (Торунь), зубры (Беловежа) и два Старых города — Краков и Варшава.","why":"Вопрос №92 пособия. В старых пособиях указано 13 объектов, но актуальное число — 17 (проверено на 2026 год); главное — назвать число и 4–5 примеров.","p":0},"geo_torun":{"c":"geografia","qru":"Чем знаменит Торунь?","qpl":"Z czego słynie Toruń?","apl":"Toruń to miasto, w którym urodził się Mikołaj Kopernik. Słynie też z pierników i gotyckiej starówki, która jest na liście UNESCO.","aru":"Торунь — город, в котором родился Николай Коперник. Он также славится пряниками и готическим старым городом, который входит в список ЮНЕСКО.","tr":"То́рунь то мя́сто, в кту́рым уродзи́л щен Мико́лай Копе́рник. Слы́не теж з перни́кув и готы́цкей стару́вки, кту́ра ест на ли́щче ЮНЭ́СКО.","mn":"Торунь = Коперник + пряник: астроном родился среди пряников.","why":"Вопрос №93 пособия: «город Коперника». Торунь часто спрашивают в связке с Коперником и торуньскими пряниками (pierniki toruńskie).","p":0},"trad_wigilia":{"c":"tradycje","qru":"Что такое Wigilia и когда её отмечают?","qpl":"Co to jest Wigilia i kiedy się ją obchodzi?","apl":"Wigilia to uroczysta kolacja w wieczór 24 grudnia. Rodzina zbiera się przy stole i czeka na pierwszą gwiazdkę, żeby zacząć kolację.","aru":"Вигилия — это торжественный ужин вечером 24 декабря. Семья собирается за столом и ждёт первой звезды, чтобы начать ужин.","tr":"Виги́лия то урочы́ста коля́цья в ве́чур двудзестэ́го чвартэ́го гру́дня. Родзи́на збе́ра щен пшы сто́ле и чэ́ка на пе́рвшон гвя́здкэ, жэ́бы зачо́нчь коля́цьен.","mn":"","why":"Wigilia (сочельник) — центральный момент польского Рождества; ужин начинают, когда на небе появляется первая звезда.","p":0},"trad_12_potraw":{"c":"tradycje","qru":"Сколько блюд традиционно подают на ужин Wigilii и почему?","qpl":"Ile potraw tradycyjnie podaje się na kolacji wigilijnej i dlaczego?","apl":"Tradycyjnie podaje się dwanaście potraw. Liczba dwanaście symbolizuje dwunastu apostołów.","aru":"Традиционно подают двенадцать блюд. Число двенадцать символизирует двенадцать апостолов.","tr":"Традыцы́йне пода́е щен двана́щче по́трав. Ли́чба двана́щче симболизу́е двуна́сту апосто́лув.","mn":"","why":"12 постных блюд — классический канон вигилийного стола, число связано с двенадцатью апостолами.","p":0},"trad_oplatek":{"c":"tradycje","qru":"Что такое opłatek и что с ним делают?","qpl":"Co to jest opłatek i co się z nim robi?","apl":"Opłatek to cienki biały chlebek. Przed kolacją wigilijną ludzie dzielą się opłatkiem i składają sobie życzenia.","aru":"Облатек — это тонкий белый хлебец. Перед вигилийным ужином люди делятся облаткой и желают друг другу добра.","tr":"Опла́тэк то че́нки бя́лы хле́бэк. Пшед коля́цьон вигили́йнон лю́дзе дзе́лён щен опла́ткем и склада́йон со́бе жычэ́ня.","mn":"","why":"Преломление облатки (opłatek) с пожеланиями — важнейший обряд примирения и единения семьи на Wigilii.","p":0},"trad_puste_miejsce":{"c":"tradycje","qru":"Зачем на вигилийном столе оставляют пустое место и кладут сено под скатерть?","qpl":"Po co przy stole wigilijnym zostawia się puste miejsce i kładzie się siano pod obrus?","apl":"Puste miejsce zostawia się dla niespodziewanego gościa lub dla kogoś, kogo nie ma. Siano pod obrusem przypomina o tym, że Jezus urodził się w stajni.","aru":"Пустое место оставляют для нежданного гостя или для того, кого нет рядом. Сено под скатертью напоминает, что Иисус родился в хлеву.","tr":"Пу́стэ ме́йсцэ зоста́вя щен для несподзеванэ́го го́щча люб для ко́гощ, ко́го не ма. Щя́но под обру́сэм пшипоми́на о тым, же Е́зус уро́дзил щен в ста́йни.","mn":"","why":"Пустой прибор — знак гостеприимства и памяти об отсутствующих; сено символизирует ясли Христа.","p":0},"trad_potrawy_wigilijne":{"c":"tradycje","qru":"Какие традиционные блюда едят на Wigilii?","qpl":"Jakie tradycyjne potrawy je się na Wigilii?","apl":"Na Wigilię je się barszcz z uszkami, karpia, pierogi z kapustą i grzybami oraz kutię. Pije się kompot z suszu. Potrawy są postne, bez mięsa.","aru":"На Вигилии едят борщ с ушками, карпа, пероги (вареники) с капустой и грибами и кутью. Пьют компот из сухофруктов. Блюда постные, без мяса.","tr":"На Виги́лью е щен баршч з ушка́ми, ка́рпя, перо́ги з капу́стон и гжиба́ми о́раз ку́тен. Пи́е щен ко́мпот з су́шу. Потра́вы сон по́стнэ, бэз мье́нса.","mn":"","why":"Классические постные блюда вигилийного стола; мясо традиционно не подают.","p":0},"trad_koledy":{"c":"tradycje","qru":"Что такое kolędy?","qpl":"Co to są kolędy?","apl":"Kolędy to pieśni bożonarodzeniowe. Śpiewa się je w czasie świąt Bożego Narodzenia. Najbardziej znana polska kolęda to „Bóg się rodzi”.","aru":"Колядки — это рождественские песни. Их поют во время праздников Рождества. Самая известная польская колядка — «Bóg się rodzi» («Бог рождается»).","tr":"Коле́нды то пе́щни божонародзэнё́вэ. Щпе́ва щен е в ча́ще щвёнт Божэ́го Народзэ́ня. Найба́рдзей зна́на по́льска коле́нда то „Буг щен ро́дзи”.","mn":"«Bóg się rodzi» — «Бог рождается»: королева польских колядок, написал Карпинский в XVIII веке.","why":"Kolędy — рождественские песнопения, неотъемлемая часть праздника; «Bóg się rodzi» Ф. Карпинского называют «королевой польских колядок».","p":0},"trad_wielkanoc":{"c":"tradycje","qru":"Что такое święconka и śmigus-dyngus на Пасху?","qpl":"Co to jest święconka i śmigus-dyngus na Wielkanoc?","apl":"Święconka to koszyczek z jedzeniem, który święci się w kościele w Wielką Sobotę. W koszyczku są pisanki, chleb, kiełbasa, sól i baranek. Śmigus-dyngus to zwyczaj polewania się wodą w poniedziałek wielkanocny.","aru":"Свенцонка — это корзинка с едой, которую освящают в костёле в Великую субботу. В корзинке — писанки (крашеные яйца), хлеб, колбаса, соль и барашек. Смигус-дынгус — обычай обливаться водой в пасхальный понедельник.","tr":"Щвенцо́нка то коши́чэк з едзэ́нем, кту́ры щве́нчи щен в кощчэ́ле в Ве́лькон Собо́тэ. В коши́чку сон писа́нки, хлеб, келба́са, суль и бара́нэк. Щми́гус-ды́нгус то звы́чай полева́ня щен во́дон в понедзя́лэк велькано́цны.","mn":"","why":"Święconka — освящение пасхальной снеди; śmigus-dyngus (Lany Poniedziałek) — обливание водой в понедельник после Пасхи.","p":0},"trad_boze_cialo":{"c":"tradycje","qru":"Что такое праздник Boże Ciało?","qpl":"Co to jest święto Bożego Ciała?","apl":"Boże Ciało to katolickie święto, zwykle w czerwcu, sześćdziesiąt dni po Wielkanocy. To dzień wolny od pracy. Wierni idą w procesji ulicami i zatrzymują się przy czterech ołtarzach.","aru":"Божье Тело — католический праздник, обычно в июне, через шестьдесят дней после Пасхи. Это нерабочий день. Верующие идут процессией по улицам и останавливаются у четырёх алтарей.","tr":"Бо́жэ Ча́ло то католи́цке щве́нто, звы́кле в чэ́рвцу, шэщчдзе́щёнт дни по Велькано́цы. То дзень во́льны од пра́цы. Ве́рни и́дон в процэ́сьи улица́ми и затшыму́ён щен пшы чтэ́рэх олта́жах.","mn":"","why":"Boże Ciało — подвижный праздник (четверг, ~60 дней после Пасхи) и государственный выходной; известно уличными процессиями с четырьмя алтарями.","p":0},"trad_andrzejki":{"c":"tradycje","qru":"Что такое andrzejki?","qpl":"Co to są andrzejki?","apl":"Andrzejki to wieczór wróżb w nocy z 29 na 30 listopada. Najbardziej znana wróżba to lanie wosku przez ucho klucza.","aru":"Анджейки — это вечер гаданий в ночь с 29 на 30 ноября. Самое известное гадание — литьё воска через отверстие ключа.","tr":"Андже́йки то ве́чур вружб в но́цы з двудзестэ́го дзевёнтэ́го на тшидзестэ́го листопа́да. Найба́рдзей зна́на вру́жба то ла́не во́ску пшэз у́хо клю́ча.","mn":"Анджейки — канун дня св. АНДЖЕЯ (Андрея), ночь 29 → 30 ноября. Гадают на воске.","why":"Andrzejki — народный вечер гаданий накануне дня святого Андрея (30 ноября), особенно популярный у молодёжи.","p":0},"trad_kuchnia_regionalna":{"c":"tradycje","qru":"Назови примеры региональных блюд Польши.","qpl":"Podaj przykłady regionalnych potraw Polski.","apl":"Na Podhalu je się oscypek, czyli ser z mleka owczego. Na Śląsku popularna jest rolada, a na Podlasiu kartacze.","aru":"На Подгалье едят осцыпек — сыр из овечьего молока. В Силезии популярна рулада, а на Подляшье — картачи.","tr":"На Подха́лю е щен осцы́пэк, чы́ли сэр з мле́ка овчэ́го. На Щлё́нску популя́рна ест роля́да, а на Подля́щу карта́чэ.","mn":"Осцыпек — «овца пёк»: копчёный овечий сыр с гор (Подгалье). Силезия — рулада, Подляшье — картачи («картошка»).","why":"Региональная кухня: góralski oscypek (Подгалье), śląska rolada, podlaskie kartacze — типичный вопрос о культурном разнообразии.","p":0},"trad_goscinnosc":{"c":"tradycje","qru":"Как в Польше выражают гостеприимство хлебом-солью?","qpl":"Jak w Polsce wyraża się gościnność chlebem i solą?","apl":"Polacy są bardzo gościnni. Tradycyjnie wita się ważnych gości chlebem i solą, na przykład na weselu.","aru":"Поляки очень гостеприимны. По традиции важных гостей встречают хлебом и солью, например на свадьбе.","tr":"Поля́цы сон ба́рдзо гощчи́нни. Традыцы́йне ви́та щен ва́жных го́щчи хле́бэм и со́лон, на пши́клад на весе́лю.","mn":"","why":"Хлеб-соль (chleb i sól) — славянский знак гостеприимства; в Польше им встречают новобрачных и почётных гостей.","p":0},"trad_trzech_kroli":{"c":"tradycje","qru":"Что такое праздник Трёх Королей и когда его отмечают?","qpl":"Co to jest święto Trzech Króli i kiedy się je obchodzi?","apl":"Święto Trzech Króli obchodzimy szóstego stycznia. Trzej Królowie to Kacper, Melchior i Baltazar, którzy przynieśli Jezusowi złoto, kadzidło i mirrę. Od dwa tysiące jedenastego roku to dzień wolny od pracy. W wielu miastach organizuje się barwne Orszaki Trzech Króli.","aru":"Праздник Трёх Королей отмечают шестого января. Три Короля — это Каспер, Мельхиор и Бальтазар, которые принесли Иисусу золото, ладан и мирру. С две тысячи одиннадцатого года это нерабочий день. Во многих городах устраивают красочные шествия Трёх Королей.","tr":"Щве́нто Тшех Кру́ли обходзи́мы шустэ́го сты́чня. Тшей Крулё́ве то Ка́цпэр, Мэ́льхёр и Бальта́зар, кту́жы пшыне́щли Езусо́ви зло́то, кадзи́дло и ми́ррэ. Од два тыщё́нцэ едэнастэ́го ро́ку то дзень во́льны од пра́цы. В ве́лю мя́стах организу́е щен ба́рвнэ Орша́ки Тшех Кру́ли.","mn":"КМБ: Кацпер, Мельхиор, Бальтазар — как «курс молодого бойца». 6.01 — выходной с 2011.","why":"Вопрос №88 банка: имена Трёх Королей и их дары. Часто уточняют, что 6 января снова выходной с 2011 года — это проверка знания актуального календаря праздников.","p":0},"trad_sroda_popielcowa":{"c":"tradycje","qru":"Что такое Пепельная среда (Środa Popielcowa)?","qpl":"Co to jest Środa Popielcowa?","apl":"Środa Popielcowa to początek Wielkiego Postu przed Wielkanocą. W kościele ksiądz posypuje głowy wiernych popiołem. Tego dnia obowiązuje post.","aru":"Пепельная среда — это начало Великого поста перед Пасхой. В костёле ксёндз посыпает головы верующих пеплом. В этот день обязателен пост.","tr":"Щро́да Попельцо́ва то почо́нтэк Вельке́го По́сту пшед Велькано́цон. В кощчэ́ле кщёндз посыпу́е гло́вы ве́рных попё́лэм. Тэ́го дня обовёнзу́е пост.","mn":"Popiół = пепел: ксёндз посыпает голову пеплом — «пепельная» среда открывает пост.","why":"Вопрос №81 банка: «чем начинается Великий пост?» — правильный ответ именно Środa Popielcowa, а не Tłusty czwartek.","p":0},"trad_niedziela_palmowa":{"c":"tradycje","qru":"Что такое Пальмовое воскресенье (Niedziela Palmowa)?","qpl":"Co to jest Niedziela Palmowa?","apl":"Niedziela Palmowa to święto na tydzień przed Wielkanocą. Wierni przynoszą do kościoła kolorowe palmy, które ksiądz święci. Święto przypomina wjazd Jezusa do Jerozolimy.","aru":"Пальмовое воскресенье — праздник за неделю до Пасхи. Верующие приносят в костёл разноцветные пальмы, которые освящает ксёндз. Праздник напоминает о въезде Иисуса в Иерусалим.","tr":"Недзе́ля Пальмо́ва то щве́нто на ты́дзень пшед Велькано́цон. Ве́рни пшино́шон до кощчё́ла колёро́вэ па́льмы, кту́рэ кщёндз щве́нчи. Щве́нто пшипоми́на вьязд Езу́са до Ерозоли́мы.","mn":"Аналог нашего Вербного воскресенья, только вместо вербы — цветные «пальмы».","why":"Вопрос №85 банка сформулирован как загадка: «какой праздник за 7 дней до Пасхи?» — нужно узнать Niedzielę Palmową и знать про освящение пальм.","p":0},"lud_chopin":{"c":"ludzie","qru":"Кто такой Фридерик Шопен?","qpl":"Kim był Fryderyk Chopin?","apl":"Fryderyk Chopin był polskim kompozytorem i pianistą. Urodził się w Żelazowej Woli koło Warszawy. Komponował przede wszystkim muzykę na fortepian, na przykład mazurki i polonezy.","aru":"Фридерик Шопен был польским композитором и пианистом. Он родился в Желязовой Воле под Варшавой. Он сочинял прежде всего музыку для фортепиано, например мазурки и полонезы.","tr":"Фридэ́рык Шо́пэн был по́льским композыто́рэм и пяни́стон. Уро́дзил ще в Жэлязо́вэй Во́ли ко́ло Варша́вы. Компоно́вал пшэ́дэ вши́стким му́зыкэ на фортэ́пян, на пши́клад мазу́рки и полонэ́зы.","mn":"","why":"Шопен (1810–1849) — величайший польский композитор-романтик, символ национальной культуры.","p":0},"lud_sklodowska":{"c":"ludzie","qru":"Чем знаменита Мария Склодовская-Кюри?","qpl":"Z czego słynie Maria Skłodowska-Curie?","apl":"Maria Skłodowska-Curie była polską uczoną. Dostała dwie Nagrody Nobla, z fizyki i z chemii, za badania nad promieniotwórczością. Odkryła dwa pierwiastki: polon i rad.","aru":"Мария Склодовская-Кюри была польской учёной. Она получила две Нобелевские премии — по физике и по химии — за исследования радиоактивности. Она открыла два элемента: полоний и радий.","tr":"Ма́рья Склодо́вска-Кюри́ была по́льскон учо́нон. Доста́ла две Нагро́ды Но́бля, з фи́зыки и з хе́мии, за бада́ня над променётвурчо́щчён. Одкры́ла два перьвя́стки: по́лён и рад.","mn":"Полоний назван в честь Польши (Polonia) — легко вспомнить первый элемент.","why":"Склодовская-Кюри — первый человек, получивший две Нобелевские премии в разных науках (физика 1903, химия 1911).","p":0},"lud_kopernik":{"c":"ludzie","qru":"Кто такой Николай Коперник и что он открыл?","qpl":"Kim był Mikołaj Kopernik i co odkrył?","apl":"Mikołaj Kopernik był wielkim polskim astronomem. Urodził się w Toruniu, a zmarł we Fromborku. Stworzył teorię, że to Ziemia krąży wokół Słońca, a nie Słońce wokół Ziemi. Jego dzieło „O obrotach sfer niebieskich” wydano w 1543 roku.","aru":"Николай Коперник был великим польским астрономом. Он родился в Торуне, а умер во Фромборке. Он создал теорию, что Земля вращается вокруг Солнца, а не Солнце вокруг Земли. Его труд «О вращениях небесных сфер» был издан в 1543 году.","tr":"Мико́лай Копэ́рник был ве́льким по́льским астроно́мэм. Уро́дзил ще в Тору́ню, а змарл вэ Фромбо́рку. Стфо́жил тэо́рьен, же то Зе́мя кро́нжи во́кул Сло́нца, а не Сло́нце во́кул Зе́ми. Е́го дзе́ло „О обро́тах сфэр небе́ских” ви́дано в ты́щёнц пеньчсэ́т чтэрдзе́стым тше́чим ро́ку.","mn":"Польская поговорка о Копернике: «Wstrzymał Słońce, ruszył Ziemię» — «Остановил Солнце, сдвинул Землю».","why":"Коперник (1473–1543) — автор гелиоцентрической системы. В пособии отдельный вопрос «miasto Kopernika» — ответ Toruń; часто уточняют, где умер (Frombork) и когда вышел его труд (1543).","p":0},"lud_jan_pawel_ii":{"c":"ludzie","qru":"Кто такой Иоанн Павел II?","qpl":"Kim był Jan Paweł II?","apl":"Jan Paweł II, czyli Karol Wojtyła, był polskim papieżem. Pochodził z Wadowic. Był głową Kościoła katolickiego od 1978 do 2005 roku.","aru":"Иоанн Павел II, то есть Кароль Войтыла, был польским Папой Римским. Он родом из Вадовиц. Он возглавлял Католическую церковь с 1978 по 2005 год.","tr":"Ян Па́вэл Дру́ги, чы́ли Ка́роль Войты́ла, был по́льским папе́жэм. Похо́дзил з Вадо́виц. Был гло́вон Кощчо́ла католицке́го од ты́щёнц дзеве́нчсэт щедэмдзе́щёнт о́смэго до два тыщё́нцэ пёнтэ́го ро́ку.","mn":"","why":"Кароль Войтыла — первый Папа-поляк, понтифик в 1978–2005 гг., канонизирован в 2014 году.","p":0},"lud_walesa":{"c":"ludzie","qru":"Кто такой Лех Валенса?","qpl":"Kim jest Lech Wałęsa?","apl":"Lech Wałęsa był przywódcą „Solidarności” i pierwszym prezydentem Polski wybranym w wolnych wyborach. Dostał też Pokojową Nagrodę Nobla.","aru":"Лех Валенса был лидером «Солидарности» и первым президентом Польши, избранным на свободных выборах. Он также получил Нобелевскую премию мира.","tr":"Лех Вауэ́нса был пшиву́дцон „Солидарно́щчи” и пе́рвшым прэзидэ́нтэм По́льски выбра́ным в во́льных выбо́рах. До́стал тэж Покоё́вон Нагро́дэ Но́бля.","mn":"","why":"Валенса — лидер профсоюза Solidarność, лауреат Нобелевской премии мира (1983), президент Польши в 1990–1995 гг.","p":0},"lud_mickiewicz":{"c":"ludzie","qru":"Кто такой Адам Мицкевич?","qpl":"Kim był Adam Mickiewicz?","apl":"Adam Mickiewicz był najważniejszym polskim poetą romantycznym, jednym z trzech wieszczów. Napisał epopeję narodową „Pan Tadeusz” i dramat „Dziady”.","aru":"Адам Мицкевич был важнейшим польским поэтом-романтиком, одним из трёх поэтов-пророков (wieszczów). Он написал национальную эпопею «Пан Тадеуш» и драму «Дзяды».","tr":"А́дам Мицке́вич был найважне́йшым по́льским поэ́тон романты́чным, е́дным з тшэх ве́щчув. Напи́сал эпопе́ен народо́вон „Пан Таде́уш” и дра́мат „Дзя́ды”.","mn":"","why":"Мицкевич (1798–1855) — национальный поэт Польши; «Pan Tadeusz» начинается словами «Litwo! Ojczyzno moja!». На собеседовании часто просят назвать и «Dziady», и остальных wieszczów.","p":0},"lud_sienkiewicz":{"c":"ludzie","qru":"Кто такой Генрик Сенкевич?","qpl":"Kim był Henryk Sienkiewicz?","apl":"Henryk Sienkiewicz był polskim pisarzem. Dostał Nagrodę Nobla, a jego najbardziej znana powieść to „Quo Vadis”. Napisał też Trylogię i powieść „Krzyżacy”.","aru":"Генрик Сенкевич был польским писателем. Он получил Нобелевскую премию, а его самый известный роман — «Камо грядеши» (Quo Vadis). Он также написал Трилогию и роман «Крестоносцы».","tr":"Хэ́нрык Щенке́вич был по́льским писа́жэм. До́стал Нагро́дэ Но́бля, а е́го найба́рдзей зна́на по́вещчь то „Кво Ва́дис”. Напи́сал тэж Трыло́гьен и по́вещчь „Кшижа́цы”.","mn":"","why":"Сенкевич — лауреат Нобелевской премии по литературе (1905); известен «Quo Vadis» и трилогией о Речи Посполитой.","p":0},"lud_lem":{"c":"ludzie","qru":"Кто такой Станислав Лем?","qpl":"Kim był Stanisław Lem?","apl":"Stanisław Lem był polskim pisarzem science fiction. Jego najbardziej znana powieść to „Solaris”.","aru":"Станислав Лем был польским писателем-фантастом. Его самый известный роман — «Солярис».","tr":"Стани́слав Лем был по́льским писа́жэм са́йенс фи́кшн. Е́го найба́рдзей зна́на по́вещчь то „Соля́рис”.","mn":"","why":"Лем (1921–2006) — крупнейший польский фантаст, переведён на десятки языков; «Solaris» экранизирован.","p":0},"lud_wajda":{"c":"ludzie","qru":"Кто такой Анджей Вайда?","qpl":"Kim był Andrzej Wajda?","apl":"Andrzej Wajda był słynnym polskim reżyserem filmowym. Dostał Oscara za całokształt twórczości. Nakręcił na przykład filmy „Katyń” i „Człowiek z żelaza”.","aru":"Анджей Вайда был знаменитым польским кинорежиссёром. Он получил «Оскар» за вклад в киноискусство. Он снял, например, фильмы «Катынь» и «Человек из железа».","tr":"А́нджей Ва́йда был слы́нным по́льским рэжисэ́рэм фильмо́вым. До́стал Оска́ра за цало́кшталт твурчо́щчи. Накрэ́нчил на пши́клад фи́льмы „Ка́тынь” и „Чло́век з жэля́за”.","mn":"","why":"Вайда (1926–2016) — классик польского кино, получил почётный «Оскар» в 2000 году.","p":0},"lud_szymborska":{"c":"ludzie","qru":"Кто такая Вислава Шимборская?","qpl":"Kim była Wisława Szymborska?","apl":"Wisława Szymborska była polską poetką. Dostała Nagrodę Nobla w dziedzinie literatury w 1996 roku.","aru":"Вислава Шимборская была польской поэтессой. Она получила Нобелевскую премию по литературе в 1996 году.","tr":"Висла́ва Шимбо́рска была по́льскон поэ́ткон. Доста́ла Нагро́дэ Но́бля в дзедзи́не литэрату́ры в ты́щёнц дзеве́нчсэт дзевенчдзе́щёнт шу́стым ро́ку.","mn":"Рифма: «Девяносто шесть — у Шимборской Нобель есть» (1996).","why":"Шимборская — лауреат Нобелевской премии по литературе (1996); ещё один польский нобелиат — поэт Чеслав Милош (1980).","p":0},"lud_trzej_wieszcze":{"c":"ludzie","qru":"Кто такие три польских поэта-пророка (trzej wieszcze)?","qpl":"Kim byli trzej wieszcze narodowi?","apl":"Trzej wieszcze to najwięksi polscy poeci romantyczni: Adam Mickiewicz, Juliusz Słowacki i Zygmunt Krasiński. Ich twórczość podtrzymywała ducha narodu w czasie zaborów.","aru":"Три «вещих» (wieszcze) — это величайшие польские поэты-романтики: Адам Мицкевич, Юлиуш Словацкий и Зигмунт Красинский. Их творчество поддерживало дух народа во времена разделов.","tr":"Тшэй ве́щчэ то найве́нкси по́льсцы поэ́чи романты́чни: А́дам Мицке́вич, Ю́люш Слова́цки и Зы́гмунт Краси́ньски. Их тву́рчощчь подтшимыва́ла ду́ха наро́ду в ча́ще забо́рув.","mn":"МСК: Мицкевич, Словацкий, Красинский — три буквы, как «Москва», только наоборот по духу.","why":"Вопрос №67 канонического банка: Мицкевича представляют как одного из trzech wieszczów и просят назвать двух остальных — Словацкого и Красинского.","p":0},"wsp_ue":{"c":"wspolczesna","qru":"Когда Польша вступила в Европейский союз?","qpl":"Kiedy Polska wstąpiła do Unii Europejskiej?","apl":"Polska wstąpiła do Unii Europejskiej 1 maja 2004 roku.","aru":"Польша вступила в Европейский союз 1 мая 2004 года.","tr":"По́льска встомпи́ла до У́нии Эуропэ́йскей первшэ́го ма́я два тыщё́нцэ чвартэ́го ро́ку.","mn":"Первомай в Евросоюзе: 1 мая 2004 Польша вошла в ЕС.","why":"Польша вошла в ЕС 1 мая 2004 года в рамках крупнейшего расширения союза.","p":0},"wsp_nato":{"c":"wspolczesna","qru":"Когда Польша вступила в НАТО?","qpl":"Kiedy Polska wstąpiła do NATO?","apl":"Polska wstąpiła do NATO 12 marca 1999 roku, razem z Czechami i Węgrami.","aru":"Польша вступила в НАТО 12 марта 1999 года, вместе с Чехией и Венгрией.","tr":"По́льска встомпи́ла до НА́ТО двунастэ́го ма́рца ты́щёнц дзе́венчсэт дзевенчдзещёнтэ́го дзевёнтэ́го ро́ку, ра́зэм з Чэха́ми и Вэнгра́ми.","mn":"НАТО — 1999: заскочили в последний год века, до миллениума.","why":"Польша стала членом НАТО 12 марта 1999 года вместе с Чехией и Венгрией.","p":0},"wsp_waluta":{"c":"wspolczesna","qru":"Какая валюта в Польше?","qpl":"Jaka waluta jest w Polsce?","apl":"Walutą Polski jest złoty, w skrócie PLN. Polska nie wprowadziła jeszcze euro.","aru":"Валюта Польши — злотый, сокращённо PLN. Польша пока не ввела евро.","tr":"Валю́тон По́льски ест зло́ты, в скру́че Пэ-эль-эн. По́льска не впровадзи́ла е́шчэ э́уро.","mn":"","why":"Польша входит в ЕС, но сохраняет национальную валюту — польский злотый (zł, PLN); евро не введено.","p":0},"wsp_ustroj":{"c":"wspolczesna","qru":"Какой государственный строй в Польше?","qpl":"Jaki ustrój polityczny ma Polska?","apl":"Polska jest republiką i demokracją parlamentarną. Parlament składa się z Sejmu i Senatu — Sejm liczy 460 posłów, a Senat 100 senatorów. Głową państwa jest prezydent, a rządem kieruje premier.","aru":"Польша — республика и парламентская демократия. Парламент состоит из Сейма и Сената — в Сейме 460 депутатов, а в Сенате 100 сенаторов. Глава государства — президент, а правительством руководит премьер.","tr":"По́льска ест рэпубли́кон и дэмокра́цьон парламэнта́рнон. Парла́мэнт скла́да ще з Сэ́йму и Сэна́ту — Сэйм ли́чы чтэ́рыста шэщдзе́щёнт по́слув, а Сэ́нат сто сэнато́рув. Гло́вон па́ньства ест прэзидэ́нт, а жо́ндэм керу́е прэ́мер.","mn":"460 + 100: Сейм — «большой зал» на 460, Сенат — ровно сотня.","why":"Классический вопрос о госстрое: ждут слова «republika», «demokracja parlamentarna» и состав парламента — Sejm (460) и Senat (100).","p":0},"wsp_prezydent":{"c":"wspolczesna","qru":"Кто сейчас президент Польши?","qpl":"Kto jest teraz prezydentem Polski?","apl":"Prezydentem Polski jest Karol Nawrocki. Objął urząd w 2025 roku, po Andrzeju Dudzie.","aru":"Президент Польши — Кароль Навроцкий. Он вступил в должность в 2025 году, после Анджея Дуды.","tr":"Прэзидэ́нтэм По́льски ест Ка́роль Навро́цки. О́бйол у́жонд в два тыщё́нцэ двудзе́стым пё́нтым ро́ку, по Анджэ́ю Ду́дзе.","mn":"Навроцкий — «на новенького»: новый президент с 2025, после Дуды.","why":"Кароль Навроцкий победил на президентских выборах 2025 года и вступил в должность 6 августа 2025-го, сменив Анджея Дуду (президент в 2015–2025).","p":0},"wsp_stolica":{"c":"wspolczesna","qru":"Какая столица и крупнейший город Польши?","qpl":"Jaka jest stolica i największe miasto Polski?","apl":"Stolicą i największym miastem Polski jest Warszawa. Mieszka tam około dwóch milionów ludzi. W Warszawie pracują prezydent, rząd i parlament, a symbolem miasta jest Syrenka.","aru":"Столица и крупнейший город Польши — Варшава. Там живёт около двух миллионов человек. В Варшаве работают президент, правительство и парламент, а символ города — Сиренка (русалка).","tr":"Столи́цон и найве́нкшым мя́стэм По́льски ест Варша́ва. Ме́шка там око́ло двух мильо́нув лю́дзи. В Варша́ве працу́йон прэзидэ́нт, жонд и парла́мэнт, а сымбо́лем мя́ста ест Сырэ́нка.","mn":"","why":"Варшава — столица и центр власти; в отличие от geo_stolica (список городов), здесь современный ракурс: органы власти и символ города — русалка Syrenka.","p":0},"wsp_premier":{"c":"wspolczesna","qru":"Кто сейчас премьер-министр Польши и чем занимается правительство?","qpl":"Kto jest teraz premierem Polski?","apl":"Premierem Polski jest Donald Tusk, od grudnia 2023 roku. Premier kieruje rządem, czyli Radą Ministrów, która prowadzi bieżącą politykę państwa.","aru":"Премьер-министр Польши — Дональд Туск, с декабря 2023 года. Премьер руководит правительством, то есть Советом министров, который ведёт текущую политику государства.","tr":"Прэме́рэм По́льски ест До́нальд Туск, од гру́дня два тыщё́нцэ двудзестэ́го тшэче́го ро́ку. Прэ́мер керу́е жо́ндэм, чы́ли Ра́дон Мини́струв, кту́ра прова́дзи бежо́нцон поли́тыкэ па́ньства.","mn":"Туск — второй заход: уже был премьером в 2007–2014, снова с декабря 2023.","why":"На собеседовании проверяют, следите ли вы за актуальной жизнью страны: кто президент и кто премьер — стандартная пара вопросов. Актуально на июль 2026.","p":0}};
